package com.mifare.encoder

import android.app.PendingIntent
import android.content.Intent
import android.content.IntentFilter
import android.nfc.NfcAdapter
import android.nfc.tech.MifareClassic
import android.os.Bundle
import android.view.Menu
import android.view.MenuItem
import androidx.appcompat.app.AlertDialog
import androidx.appcompat.app.AppCompatActivity
import androidx.fragment.app.Fragment
import com.google.android.material.tabs.TabLayout
import com.mifare.encoder.databinding.ActivityAdminModeBinding
import com.mifare.encoder.fragments.*
import com.mifare.encoder.utils.AuthManager

class AdminModeActivity : AppCompatActivity() {

    private lateinit var binding: ActivityAdminModeBinding
    private lateinit var authManager: AuthManager

    // NFC handling
    private var nfcAdapter: NfcAdapter? = null
    private var pendingIntent: PendingIntent? = null
    private var intentFilters: Array<IntentFilter>? = null
    private var techLists: Array<Array<String>>? = null

    // Fragment instances
    private val scanFragment = AdminScanFragment()
    private val writeFragment = AdminWriteFragment()
    private val configFragment = AdminConfigFragment()
    private val logsFragment = AdminLogsFragment()

    companion object {
        private const val TAG = "AdminModeActivity"
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        binding = ActivityAdminModeBinding.inflate(layoutInflater)
        setContentView(binding.root)

        authManager = AuthManager.getInstance(this)

        // Verify admin access
        if (!authManager.isAdminMode()) {
            // Not authenticated, return to user mode
            returnToUserMode()
            return
        }

        // SECURITY: Defensive migration check (secondary safety net)
        performDefensiveMigration()

        // Check if first-run password change is required
        if (authManager.isFirstRunPasswordChangeRequired()) {
            showFirstRunPasswordChangeDialog()
            return
        }

        setupToolbar()
        setupTabs()
        setupNFC()

        // Show scan fragment by default
        showFragment(scanFragment)
    }

    private fun setupToolbar() {
        setSupportActionBar(binding.toolbar)
        supportActionBar?.title = "Admin Mode"
        supportActionBar?.subtitle = "Full Access Enabled"
    }

    private fun setupTabs() {
        binding.tabLayout.addTab(binding.tabLayout.newTab().setText("Scan").setIcon(R.drawable.ic_nfc_scan))
        binding.tabLayout.addTab(binding.tabLayout.newTab().setText("Write").setIcon(R.drawable.ic_nfc_write))
        binding.tabLayout.addTab(binding.tabLayout.newTab().setText("Config").setIcon(R.drawable.ic_settings))
        binding.tabLayout.addTab(binding.tabLayout.newTab().setText("Logs").setIcon(R.drawable.ic_logs))

        binding.tabLayout.addOnTabSelectedListener(object : TabLayout.OnTabSelectedListener {
            override fun onTabSelected(tab: TabLayout.Tab?) {
                when (tab?.position) {
                    0 -> showFragment(scanFragment)
                    1 -> showFragment(writeFragment)
                    2 -> showFragment(configFragment)
                    3 -> showFragment(logsFragment)
                }

                // Extend session on activity
                authManager.extendSession()
            }

            override fun onTabUnselected(tab: TabLayout.Tab?) {}
            override fun onTabReselected(tab: TabLayout.Tab?) {}
        })
    }

    private fun setupNFC() {
        nfcAdapter = NfcAdapter.getDefaultAdapter(this)

        if (nfcAdapter != null) {
            pendingIntent = PendingIntent.getActivity(
                this, 0,
                Intent(this, javaClass).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP),
                PendingIntent.FLAG_MUTABLE
            )

            val mifareFilter = IntentFilter(NfcAdapter.ACTION_TECH_DISCOVERED)
            intentFilters = arrayOf(mifareFilter)
            techLists = arrayOf(arrayOf(MifareClassic::class.java.name))
        }
    }

    private fun showFirstRunPasswordChangeDialog() {
        val input = android.widget.EditText(this)
        input.inputType = android.text.InputType.TYPE_CLASS_TEXT or android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD
        input.hint = "New secure admin password"

        val dialog = AlertDialog.Builder(this)
            .setTitle("First Run: Change Default Password")
            .setMessage("For security, you must change the default admin password before using admin features.\n\nNew password must be at least 8 characters.")
            .setView(input)
            .setPositiveButton("Change Password") { _, _ ->
                val newPassword = input.text.toString()
                if (newPassword.length >= 8) {
                    authManager.setAdminPassword(newPassword)
                    authManager.markFirstRunPasswordChanged()
                    android.widget.Toast.makeText(this, "Admin password updated successfully", android.widget.Toast.LENGTH_SHORT).show()

                    // Now proceed with normal admin setup
                    setupToolbar()
                    setupTabs()
                    setupNFC()
                    showFragment(scanFragment)
                } else {
                    android.widget.Toast.makeText(this, "Password must be at least 8 characters", android.widget.Toast.LENGTH_LONG).show()
                    showFirstRunPasswordChangeDialog() // Try again
                }
            }
            .setCancelable(false)
            .create()

        dialog.show()
    }

    private fun performDefensiveMigration() {
        // SECURITY: Secondary safety net for legacy plaintext cleanup
        try {
            // Clean up any remaining plaintext files as defensive measure
            deleteSharedPreferences("admin_config")
            deleteSharedPreferences("user_config")
        } catch (e: Exception) {
            // Fallback: clear content if deletion fails
            getSharedPreferences("admin_config", MODE_PRIVATE).edit().clear().apply()
            getSharedPreferences("user_config", MODE_PRIVATE).edit().clear().apply()
        }
    }

    private fun showFragment(fragment: Fragment) {
        supportFragmentManager.beginTransaction()
            .replace(R.id.fragmentContainer, fragment)
            .commit()
    }

    override fun onCreateOptionsMenu(menu: Menu?): Boolean {
        menuInflater.inflate(R.menu.admin_menu, menu)
        return true
    }

    override fun onOptionsItemSelected(item: MenuItem): Boolean {
        return when (item.itemId) {
            R.id.action_user_mode -> {
                showUserModeDialog()
                true
            }
            R.id.action_change_password -> {
                showChangePasswordDialog()
                true
            }
            R.id.action_clear_logs -> {
                showClearLogsDialog()
                true
            }
            else -> super.onOptionsItemSelected(item)
        }
    }

    private fun showUserModeDialog() {
        AlertDialog.Builder(this)
            .setTitle("Switch to User Mode")
            .setMessage("Return to simplified user interface?")
            .setPositiveButton("Switch") { _, _ ->
                returnToUserMode()
            }
            .setNegativeButton("Cancel", null)
            .show()
    }

    private fun showChangePasswordDialog() {
        val input = android.widget.EditText(this)
        input.inputType = android.text.InputType.TYPE_CLASS_TEXT or android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD
        input.hint = "New admin password"

        AlertDialog.Builder(this)
            .setTitle("Change Admin Password")
            .setMessage("Enter new password:")
            .setView(input)
            .setPositiveButton("Change") { _, _ ->
                val newPassword = input.text.toString()
                if (newPassword.length >= 8) {
                    authManager.setAdminPassword(newPassword)
                    android.widget.Toast.makeText(this, "Password updated", android.widget.Toast.LENGTH_SHORT).show()
                } else {
                    android.widget.Toast.makeText(this, "Password must be at least 8 characters", android.widget.Toast.LENGTH_SHORT).show()
                }
            }
            .setNegativeButton("Cancel", null)
            .show()
    }

    private fun showClearLogsDialog() {
        AlertDialog.Builder(this)
            .setTitle("Clear Admin Logs")
            .setMessage("This will delete all admin activity logs. Continue?")
            .setPositiveButton("Clear") { _, _ ->
                authManager.clearAdminLogs()
                android.widget.Toast.makeText(this, "Logs cleared", android.widget.Toast.LENGTH_SHORT).show()

                // Refresh logs fragment if currently visible
                if (binding.tabLayout.selectedTabPosition == 3) {
                    logsFragment.refreshLogs()
                }
            }
            .setNegativeButton("Cancel", null)
            .show()
    }

    private fun returnToUserMode() {
        authManager.setUserMode()
        startActivity(Intent(this, UserModeActivity::class.java))
        finish()
    }

    override fun onResume() {
        super.onResume()

        // Check if session is still valid
        if (!authManager.isAdminMode()) {
            returnToUserMode()
            return
        }

        // Enable NFC foreground dispatch for admin fragments
        nfcAdapter?.enableForegroundDispatch(this, pendingIntent, intentFilters, techLists)
    }

    override fun onPause() {
        super.onPause()
        nfcAdapter?.disableForegroundDispatch(this)
    }

    override fun onNewIntent(intent: Intent?) {
        super.onNewIntent(intent)
        setIntent(intent)

        // Forward NFC intents to the appropriate admin fragment
        intent?.let { nfcIntent ->
            if (NfcAdapter.ACTION_TECH_DISCOVERED == nfcIntent.action) {
                when (binding.tabLayout.selectedTabPosition) {
                    0 -> scanFragment.handleNfcIntent(nfcIntent) // Scan fragment
                    1 -> writeFragment.handleNfcIntent(nfcIntent) // Write fragment
                }
            }
        }
    }
}

package com.mifare.encoder

import android.app.PendingIntent
import android.content.Intent
import android.content.IntentFilter
import android.nfc.NfcAdapter
import android.nfc.Tag
import android.nfc.tech.MifareClassic
import android.os.Bundle
import android.util.Log
import android.widget.Toast
import androidx.appcompat.app.AppCompatActivity
import androidx.recyclerview.widget.LinearLayoutManager
import com.mifare.encoder.adapters.CardDataAdapter
import com.mifare.encoder.databinding.ActivityCardScanBinding
import com.mifare.encoder.models.CardData
import com.mifare.encoder.utils.MifareUtils
import com.mifare.encoder.utils.SaltoProtocol

class CardScanActivity : AppCompatActivity() {

    private lateinit var binding: ActivityCardScanBinding
    private var nfcAdapter: NfcAdapter? = null
    private var pendingIntent: PendingIntent? = null
    private lateinit var cardDataAdapter: CardDataAdapter

    companion object {
        private const val TAG = "CardScanActivity"
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        binding = ActivityCardScanBinding.inflate(layoutInflater)
        setContentView(binding.root)

        setupToolbar()
        setupNFC()
        setupRecyclerView()

        binding.instructionText.text = getString(R.string.hold_card_near)
    }

    private fun setupToolbar() {
        setSupportActionBar(binding.toolbar)
        supportActionBar?.setDisplayHomeAsUpEnabled(true)
        title = getString(R.string.scan_card)
    }

    private fun setupNFC() {
        nfcAdapter = NfcAdapter.getDefaultAdapter(this)

        pendingIntent = PendingIntent.getActivity(
            this, 0,
            Intent(this, javaClass).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP),
            PendingIntent.FLAG_MUTABLE
        )
    }

    private fun setupRecyclerView() {
        cardDataAdapter = CardDataAdapter()
        binding.cardDataRecyclerView.apply {
            layoutManager = LinearLayoutManager(this@CardScanActivity)
            adapter = cardDataAdapter
        }
    }

    override fun onNewIntent(intent: Intent?) {
        super.onNewIntent(intent)
        setIntent(intent)

        if (NfcAdapter.ACTION_TECH_DISCOVERED == intent?.action) {
            val tag = intent.getParcelableExtra<Tag>(NfcAdapter.EXTRA_TAG)
            if (tag != null) {
                handleCard(tag)
            }
        }
    }

    private fun handleCard(tag: Tag) {
        binding.instructionText.text = getString(R.string.card_detected)

        try {
            val mifareCard = MifareClassic.get(tag)
            if (mifareCard != null) {
                readCard(mifareCard)
            } else {
                Toast.makeText(this, "Not a MIFARE Classic card", Toast.LENGTH_SHORT).show()
            }
        } catch (e: Exception) {
            Log.e(TAG, "Error handling card", e)
            Toast.makeText(this, getString(R.string.card_read_failed), Toast.LENGTH_SHORT).show()
        }
    }

    private fun readCard(mifareCard: MifareClassic) {
        try {
            mifareCard.connect()

            val cardData = CardData()
            cardData.uid = MifareUtils.bytesToHex(mifareCard.tag.id)
            cardData.type = when (mifareCard.type) {
                MifareClassic.TYPE_CLASSIC -> "MIFARE Classic"
                MifareClassic.TYPE_PLUS -> "MIFARE Plus"
                MifareClassic.TYPE_PRO -> "MIFARE Pro"
                else -> "Unknown"
            }
            cardData.size = "${mifareCard.size} bytes"

            // Read all sectors
            val allSectorData = mutableListOf<String>()
            val sectorCount = mifareCard.sectorCount

            for (sectorIndex in 0 until sectorCount) {
                if (authenticateSector(mifareCard, sectorIndex)) {
                    val sectorData = readSector(mifareCard, sectorIndex)
                    allSectorData.add("Sector $sectorIndex: ${MifareUtils.bytesToHex(sectorData)}")
                } else {
                    allSectorData.add("Sector $sectorIndex: Authentication failed")
                }
            }

            cardData.sectors = allSectorData

            // Analyze Salto data
            val saltoData = SaltoProtocol.analyzeCard(allSectorData)
            cardData.saltoData = saltoData

            // Update UI
            runOnUiThread {
                cardDataAdapter.updateData(cardData)
                binding.instructionText.text = getString(R.string.card_read_success)
                Toast.makeText(this, getString(R.string.card_read_success), Toast.LENGTH_SHORT).show()
            }

        } catch (e: Exception) {
            Log.e(TAG, "Error reading card", e)
            runOnUiThread {
                Toast.makeText(this, getString(R.string.card_read_failed) + ": ${e.message}", Toast.LENGTH_LONG).show()
            }
        } finally {
            try {
                mifareCard.close()
            } catch (e: Exception) {
                Log.e(TAG, "Error closing card connection", e)
            }
        }
    }

    private fun authenticateSector(mifareCard: MifareClassic, sectorIndex: Int): Boolean {
        // Try common default keys
        val defaultKeys = arrayOf(
            MifareClassic.KEY_DEFAULT,
            MifareClassic.KEY_MIFARE_APPLICATION_DIRECTORY,
            MifareClassic.KEY_NFC_FORUM,
            // Add more common keys as needed
            byteArrayOf(0xFF.toByte(), 0xFF.toByte(), 0xFF.toByte(), 0xFF.toByte(), 0xFF.toByte(), 0xFF.toByte())
        )

        for (key in defaultKeys) {
            try {
                if (mifareCard.authenticateSectorWithKeyA(sectorIndex, key) ||
                    mifareCard.authenticateSectorWithKeyB(sectorIndex, key)) {
                    return true
                }
            } catch (e: Exception) {
                // Continue trying other keys
            }
        }

        return false
    }

    private fun readSector(mifareCard: MifareClassic, sectorIndex: Int): ByteArray {
        val firstBlockIndex = mifareCard.sectorToBlock(sectorIndex)
        val blockCount = mifareCard.getBlockCountInSector(sectorIndex)
        val sectorData = ByteArray(blockCount * MifareClassic.BLOCK_SIZE)

        for (i in 0 until blockCount - 1) { // Skip trailer block
            val blockData = mifareCard.readBlock(firstBlockIndex + i)
            System.arraycopy(blockData, 0, sectorData, i * MifareClassic.BLOCK_SIZE, MifareClassic.BLOCK_SIZE)
        }

        return sectorData
    }

    override fun onResume() {
        super.onResume()
        val intentFilter = IntentFilter(NfcAdapter.ACTION_TECH_DISCOVERED)
        val intentFiltersArray = arrayOf(intentFilter)
        val techListsArray = arrayOf(arrayOf<String>(MifareClassic::class.java.name))

        nfcAdapter?.enableForegroundDispatch(this, pendingIntent, intentFiltersArray, techListsArray)
    }

    override fun onPause() {
        super.onPause()
        nfcAdapter?.disableForegroundDispatch(this)
    }

    override fun onSupportNavigateUp(): Boolean {
        onBackPressed()
        return true
    }
}

package com.mifare.encoder

import android.app.PendingIntent
import android.content.Intent
import android.content.IntentFilter
import android.nfc.NfcAdapter
import android.nfc.Tag
import android.nfc.tech.MifareClassic
import android.os.Bundle
import android.util.Log
import android.widget.Toast
import androidx.appcompat.app.AppCompatActivity
import androidx.appcompat.app.AlertDialog
import com.mifare.encoder.databinding.ActivityCardWriteBinding
import com.mifare.encoder.models.CustomCardConfig
import com.mifare.encoder.utils.SaltoProtocol

class CardWriteActivity : AppCompatActivity() {

    private lateinit var binding: ActivityCardWriteBinding
    private var nfcAdapter: NfcAdapter? = null
    private var pendingIntent: PendingIntent? = null
    private var customConfig: CustomCardConfig? = null

    companion object {
        private const val TAG = "CardWriteActivity"
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        binding = ActivityCardWriteBinding.inflate(layoutInflater)
        setContentView(binding.root)

        setupToolbar()
        setupNFC()
        setupUI()
    }

    private fun setupToolbar() {
        setSupportActionBar(binding.toolbar)
        supportActionBar?.setDisplayHomeAsUpEnabled(true)
        title = getString(R.string.write_card)
    }

    private fun setupNFC() {
        nfcAdapter = NfcAdapter.getDefaultAdapter(this)

        if (nfcAdapter == null) {
            Toast.makeText(this, getString(R.string.nfc_not_supported), Toast.LENGTH_LONG).show()
            finish()
            return
        }

        pendingIntent = PendingIntent.getActivity(
            this, 0,
            Intent(this, javaClass).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP),
            PendingIntent.FLAG_MUTABLE
        )
    }

    private fun setupUI() {
        binding.encodeButton.setOnClickListener {
            validateAndPrepareData()
        }

        // Set example dates
        val currentTime = System.currentTimeMillis()
        val startDate = java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss'Z'", java.util.Locale.US)
            .format(java.util.Date(currentTime))
        val endDate = java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss'Z'", java.util.Locale.US)
            .format(java.util.Date(currentTime + 30 * 24 * 60 * 60 * 1000L)) // 30 days later

        binding.startDateEditText.setText(startDate)
        binding.endDateEditText.setText(endDate)

        // Set example data
        binding.userIdEditText.setText("12345")
        binding.accessDoorsEditText.setText("101,102,103,201")
        binding.notesEditText.setText("Hotel guest access")
    }

    private fun validateAndPrepareData() {
        val config = CustomCardConfig(
            userId = binding.userIdEditText.text.toString().trim(),
            accessDoors = binding.accessDoorsEditText.text.toString().trim(),
            startDate = binding.startDateEditText.text.toString().trim(),
            endDate = binding.endDateEditText.text.toString().trim(),
            notes = binding.notesEditText.text.toString().trim()
        )

        val errors = SaltoProtocol.validateCustomConfig(config)

        if (errors.isNotEmpty()) {
            AlertDialog.Builder(this)
                .setTitle("Validation Errors")
                .setMessage(errors.joinToString("\n"))
                .setPositiveButton("OK", null)
                .show()
            return
        }

        customConfig = config
        binding.statusText.text = "Configuration valid. Hold a blank MIFARE card near the device to write."
        binding.encodeButton.isEnabled = false
    }

    override fun onNewIntent(intent: Intent?) {
        super.onNewIntent(intent)
        setIntent(intent)

        if (NfcAdapter.ACTION_TECH_DISCOVERED == intent?.action && customConfig != null) {
            val tag = intent.getParcelableExtra<Tag>(NfcAdapter.EXTRA_TAG)
            if (tag != null) {
                writeCard(tag)
            }
        }
    }

    private fun writeCard(tag: Tag) {
        binding.statusText.text = "Writing card..."

        try {
            val mifareCard = MifareClassic.get(tag)
            if (mifareCard == null) {
                Toast.makeText(this, "Not a MIFARE Classic card", Toast.LENGTH_SHORT).show()
                return
            }

            mifareCard.connect()

            val cardData = SaltoProtocol.generateCustomCardData(customConfig!!)
            val success = writeCardData(mifareCard, cardData)

            if (success) {
                binding.statusText.text = getString(R.string.card_write_success)
                Toast.makeText(this, getString(R.string.card_write_success), Toast.LENGTH_SHORT).show()

                // Reset form
                customConfig = null
                binding.encodeButton.isEnabled = true
            } else {
                binding.statusText.text = getString(R.string.card_write_failed)
                Toast.makeText(this, getString(R.string.card_write_failed), Toast.LENGTH_SHORT).show()
            }

        } catch (e: Exception) {
            Log.e(TAG, "Error writing card", e)
            binding.statusText.text = getString(R.string.card_write_failed) + ": ${e.message}"
            Toast.makeText(this, getString(R.string.card_write_failed), Toast.LENGTH_LONG).show()
        }
    }

    private fun writeCardData(mifareCard: MifareClassic, data: ByteArray): Boolean {
        try {
            val sectorCount = mifareCard.sectorCount
            var dataOffset = 0

            // Start from sector 1 (skip sector 0 which contains manufacturer data)
            for (sectorIndex in 1 until sectorCount) {
                if (!authenticateWriteSector(mifareCard, sectorIndex)) {
                    Log.w(TAG, "Failed to authenticate sector $sectorIndex for writing")
                    continue
                }

                val firstBlock = mifareCard.sectorToBlock(sectorIndex)
                val blockCount = mifareCard.getBlockCountInSector(sectorIndex)

                // Write all blocks except the trailer block
                for (blockIndex in 0 until blockCount - 1) {
                    if (dataOffset + 16 <= data.size) {
                        val blockData = data.sliceArray(dataOffset until dataOffset + 16)
                        mifareCard.writeBlock(firstBlock + blockIndex, blockData)
                        dataOffset += 16
                    }
                }
            }

            // Verify by reading back
            return verifyWrittenData(mifareCard, data)

        } catch (e: Exception) {
            Log.e(TAG, "Error writing card data", e)
            return false
        } finally {
            try {
                mifareCard.close()
            } catch (e: Exception) {
                Log.e(TAG, "Error closing card connection", e)
            }
        }
    }

    private fun authenticateWriteSector(mifareCard: MifareClassic, sectorIndex: Int): Boolean {
        // Try default keys for writing
        val defaultKeys = arrayOf(
            MifareClassic.KEY_DEFAULT,
            byteArrayOf(0xFF.toByte(), 0xFF.toByte(), 0xFF.toByte(), 0xFF.toByte(), 0xFF.toByte(), 0xFF.toByte())
        )

        for (key in defaultKeys) {
            try {
                if (mifareCard.authenticateSectorWithKeyA(sectorIndex, key)) {
                    return true
                }
            } catch (e: Exception) {
                // Continue trying other keys
            }
        }

        return false
    }

    private fun verifyWrittenData(mifareCard: MifareClassic, originalData: ByteArray): Boolean {
        try {
            // Sample verification - read a few key blocks and compare
            var dataOffset = 64 // Start from sector 1

            for (sectorIndex in 1..3) { // Verify first few sectors
                if (authenticateWriteSector(mifareCard, sectorIndex)) {
                    val firstBlock = mifareCard.sectorToBlock(sectorIndex)
                    val readData = mifareCard.readBlock(firstBlock)
                    val expectedData = originalData.sliceArray(dataOffset until dataOffset + 16)

                    if (!readData.contentEquals(expectedData)) {
                        Log.w(TAG, "Verification failed at sector $sectorIndex")
                        return false
                    }

                    dataOffset += 64 // Next sector
                }
            }

            return true

        } catch (e: Exception) {
            Log.e(TAG, "Error verifying written data", e)
            return false
        }
    }

    override fun onResume() {
        super.onResume()
        val intentFilter = IntentFilter(NfcAdapter.ACTION_TECH_DISCOVERED)
        val intentFiltersArray = arrayOf(intentFilter)
        val techListsArray = arrayOf(arrayOf<String>(MifareClassic::class.java.name))

        nfcAdapter?.enableForegroundDispatch(this, pendingIntent, intentFiltersArray, techListsArray)
    }

    override fun onPause() {
        super.onPause()
        nfcAdapter?.disableForegroundDispatch(this)
    }

    override fun onSupportNavigateUp(): Boolean {
        onBackPressed()
        return true
    }
}

package com.mifare.encoder

import android.content.Intent
import android.nfc.NfcAdapter
import android.os.Bundle
import androidx.appcompat.app.AppCompatActivity
import com.mifare.encoder.fragments.AdminScanFragment
import com.mifare.encoder.fragments.AdminWriteFragment
import com.mifare.encoder.utils.AuthManager

/**
 * Main Activity - Entry point that routes to appropriate mode
 * 
 * This activity determines whether to show the simplified user interface
 * or redirect to admin mode if already authenticated.
 */
class MainActivity : AppCompatActivity() {

    private lateinit var authManager: AuthManager

    companion object {
        private const val TAG = "MainActivity"
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        authManager = AuthManager.getInstance(this)

        // Route to appropriate mode based on authentication state
        routeToAppropriateMode()
    }

    private fun routeToAppropriateMode() {
        if (authManager.isAdminMode()) {
            // User is already authenticated as admin
            startActivity(Intent(this, AdminModeActivity::class.java))
        } else {
            // Default to user mode
            startActivity(Intent(this, UserModeActivity::class.java))
        }

        finish() // Close MainActivity since it's just a router
    }

    override fun onNewIntent(intent: Intent?) {
        super.onNewIntent(intent)

        // Handle NFC intents if they come to MainActivity
        // Forward to appropriate activity based on current mode
        intent?.let { nfcIntent ->
            if (NfcAdapter.ACTION_TECH_DISCOVERED == nfcIntent.action) {
                if (authManager.isAdminMode()) {
                    // Forward to admin mode
                    val adminIntent = Intent(this, AdminModeActivity::class.java)
                    adminIntent.action = nfcIntent.action
                    adminIntent.putExtras(nfcIntent.extras ?: Bundle())
                    startActivity(adminIntent)
                } else {
                    // Forward to user mode
                    val userIntent = Intent(this, UserModeActivity::class.java)
                    userIntent.action = nfcIntent.action
                    userIntent.putExtras(nfcIntent.extras ?: Bundle())
                    startActivity(userIntent)
                }
                finish()
            }
        }
    }
}

package com.mifare.encoder

import android.app.Application
import android.util.Log
import androidx.security.crypto.EncryptedSharedPreferences
import androidx.security.crypto.MasterKey

/**
 * Application class for global initialization and security migration
 */
class MifareApplication : Application() {

    companion object {
        private const val TAG = "MifareApplication"
        private const val MIGRATION_FLAG_KEY = "global_migration_v2_complete"
    }

    override fun onCreate() {
        super.onCreate()

        // CRITICAL: Perform global one-time migration on app startup
        performGlobalSecurityMigration()
    }

    private fun performGlobalSecurityMigration() {
        try {
            val masterKey = MasterKey.Builder(this)
                .setKeyScheme(MasterKey.KeyScheme.AES256_GCM)
                .build()

            val securePrefs = EncryptedSharedPreferences.create(
                this,
                "admin_config_secure",
                masterKey,
                EncryptedSharedPreferences.PrefKeyEncryptionScheme.AES256_SIV,
                EncryptedSharedPreferences.PrefValueEncryptionScheme.AES256_GCM
            )

            // Check if global migration already completed
            val migrationComplete = securePrefs.getBoolean(MIGRATION_FLAG_KEY, false)

            if (!migrationComplete) {
                Log.i(TAG, "Starting global security migration...")

                // Migrate legacy user_config (user mode settings)
                migrateUserConfig(securePrefs)

                // Migrate legacy admin_config (admin mode settings) 
                migrateAdminConfig(securePrefs)

                // Mark migration as complete
                securePrefs.edit()
                    .putBoolean(MIGRATION_FLAG_KEY, true)
                    .apply()

                Log.i(TAG, "Global security migration completed successfully")
            }

        } catch (e: Exception) {
            Log.e(TAG, "Global security migration failed", e)
        }
    }

    private fun migrateUserConfig(securePrefs: android.content.SharedPreferences) {
        val userPrefs = getSharedPreferences("user_config", MODE_PRIVATE)
        val existingUrl = userPrefs.getString("backend_url", null)
        val existingApiKey = userPrefs.getString("api_key", null)

        if (!existingUrl.isNullOrEmpty() || !existingApiKey.isNullOrEmpty()) {
            // Migrate to secure storage
            securePrefs.edit()
                .putString("user_mode_url", existingUrl ?: "http://10.0.2.2:5000")
                .putString("user_mode_api_key", existingApiKey ?: "user-mode-key")
                .apply()

            Log.i(TAG, "Migrated user_config to encrypted storage")
        }

        // Clean up plaintext storage
        try {
            deleteSharedPreferences("user_config")
            Log.i(TAG, "Deleted plaintext user_config file")
        } catch (e: Exception) {
            userPrefs.edit().clear().apply()
            Log.w(TAG, "Cleared user_config (deletion failed)", e)
        }
    }

    private fun migrateAdminConfig(securePrefs: android.content.SharedPreferences) {
        val adminPrefs = getSharedPreferences("admin_config", MODE_PRIVATE)
        val existingUrl = adminPrefs.getString("backend_url", null)
        val existingApiKey = adminPrefs.getString("api_key", null)
        val existingUserUrl = adminPrefs.getString("user_mode_url", null)
        val existingUserApiKey = adminPrefs.getString("user_mode_api_key", null)

        if (!existingUrl.isNullOrEmpty() || !existingApiKey.isNullOrEmpty() ||
            !existingUserUrl.isNullOrEmpty() || !existingUserApiKey.isNullOrEmpty()) {

            // Migrate admin config to secure storage
            val editor = securePrefs.edit()

            if (!existingUrl.isNullOrEmpty()) {
                editor.putString("backend_url", existingUrl)
            }
            if (!existingApiKey.isNullOrEmpty()) {
                editor.putString("api_key", existingApiKey)
            }
            if (!existingUserUrl.isNullOrEmpty()) {
                editor.putString("user_mode_url", existingUserUrl)
            }
            if (!existingUserApiKey.isNullOrEmpty()) {
                editor.putString("user_mode_api_key", existingUserApiKey)
            }

            editor.apply()
            Log.i(TAG, "Migrated admin_config to encrypted storage")
        }

        // Clean up plaintext storage
        try {
            deleteSharedPreferences("admin_config")
            Log.i(TAG, "Deleted plaintext admin_config file")
        } catch (e: Exception) {
            adminPrefs.edit().clear().apply()
            Log.w(TAG, "Cleared admin_config (deletion failed)", e)
        }
    }
}

package com.mifare.encoder

import android.content.SharedPreferences
import android.os.Bundle
import android.util.Log
import android.widget.Toast
import androidx.appcompat.app.AppCompatActivity
import androidx.lifecycle.lifecycleScope
import com.mifare.encoder.databinding.ActivityRemoteConfigBinding
import com.mifare.encoder.models.ApiResponse
import com.mifare.encoder.models.RemoteConfig
import com.mifare.encoder.utils.ApiClient
import kotlinx.coroutines.launch

class RemoteConfigActivity : AppCompatActivity() {

    private lateinit var binding: ActivityRemoteConfigBinding
    private lateinit var prefs: SharedPreferences
    private var apiClient: ApiClient? = null

    companion object {
        private const val TAG = "RemoteConfigActivity"
        private const val PREFS_NAME = "remote_config"
        private const val KEY_BACKEND_URL = "backend_url"
        private const val KEY_API_KEY = "api_key"
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        binding = ActivityRemoteConfigBinding.inflate(layoutInflater)
        setContentView(binding.root)

        setupToolbar()
        setupPreferences()
        setupUI()
        loadSavedConfig()
    }

    private fun setupToolbar() {
        setSupportActionBar(binding.toolbar)
        supportActionBar?.setDisplayHomeAsUpEnabled(true)
        title = getString(R.string.remote_config)
    }

    private fun setupPreferences() {
        prefs = getSharedPreferences(PREFS_NAME, MODE_PRIVATE)
    }

    private fun setupUI() {
        binding.connectButton.setOnClickListener {
            testConnection()
        }

        binding.fetchConfigButton.setOnClickListener {
            fetchRemoteConfig()
        }

        // Set default backend URL if empty
        if (binding.backendUrlEditText.text.isNullOrEmpty()) {
            binding.backendUrlEditText.setText("http://localhost:5000")
        }
    }

    private fun loadSavedConfig() {
        val savedUrl = prefs.getString(KEY_BACKEND_URL, "")
        val savedApiKey = prefs.getString(KEY_API_KEY, "")

        if (!savedUrl.isNullOrEmpty()) {
            binding.backendUrlEditText.setText(savedUrl)
        }

        if (!savedApiKey.isNullOrEmpty()) {
            binding.apiKeyEditText.setText(savedApiKey)
        }

        if (!savedUrl.isNullOrEmpty() && !savedApiKey.isNullOrEmpty()) {
            updateConnectionStatus(true, "Saved configuration loaded")
        }
    }

    private fun saveConfig() {
        val url = binding.backendUrlEditText.text.toString().trim()
        val apiKey = binding.apiKeyEditText.text.toString().trim()

        prefs.edit()
            .putString(KEY_BACKEND_URL, url)
            .putString(KEY_API_KEY, apiKey)
            .apply()
    }

    private fun testConnection() {
        val url = binding.backendUrlEditText.text.toString().trim()
        val apiKey = binding.apiKeyEditText.text.toString().trim()

        if (url.isEmpty()) {
            Toast.makeText(this, "Backend URL is required", Toast.LENGTH_SHORT).show()
            return
        }

        updateConnectionStatus(false, "Testing connection...")

        lifecycleScope.launch {
            try {
                apiClient = ApiClient(url, apiKey)
                val response = apiClient!!.testConnection()

                if (response.success) {
                    updateConnectionStatus(true, "Connected successfully")
                    saveConfig()
                    Toast.makeText(this@RemoteConfigActivity, "Connection successful!", Toast.LENGTH_SHORT).show()
                } else {
                    updateConnectionStatus(false, "Connection failed: ${response.message}")
                    Toast.makeText(this@RemoteConfigActivity, "Connection failed: ${response.message}", Toast.LENGTH_LONG).show()
                }
            } catch (e: Exception) {
                Log.e(TAG, "Connection error", e)
                updateConnectionStatus(false, "Connection error: ${e.message}")
                Toast.makeText(this@RemoteConfigActivity, "Connection error: ${e.message}", Toast.LENGTH_LONG).show()
            }
        }
    }

    private fun fetchRemoteConfig() {
        if (apiClient == null) {
            Toast.makeText(this, "Please connect first", Toast.LENGTH_SHORT).show()
            return
        }

        // Example of fetching a pre-configured card program
        val userId = binding.sampleUserIdEditText.text.toString().trim()
        val doors = binding.sampleDoorsEditText.text.toString().trim()

        if (userId.isEmpty() || doors.isEmpty()) {
            Toast.makeText(this, "Please fill in user ID and doors", Toast.LENGTH_SHORT).show()
            return
        }

        binding.fetchStatus.text = "Fetching configuration..."

        lifecycleScope.launch {
            try {
                val config = mapOf(
                    "userId" to userId,
                    "doors" to doors,
                    "startDate" to "2025-01-01T00:00:00Z",
                    "endDate" to "2025-12-31T23:59:59Z",
                    "notes" to "Remote generated config"
                )

                val response = apiClient!!.generateConfig(config)

                if (response.success && response.cardData.isNotEmpty()) {
                    binding.fetchStatus.text = "Configuration received successfully!\nCard data: ${response.cardData.take(50)}..."
                    Toast.makeText(this@RemoteConfigActivity, "Configuration fetched successfully!", Toast.LENGTH_SHORT).show()
                } else {
                    binding.fetchStatus.text = "Failed to fetch configuration: ${response.message}"
                    Toast.makeText(this@RemoteConfigActivity, "Failed to fetch configuration", Toast.LENGTH_SHORT).show()
                }

            } catch (e: Exception) {
                Log.e(TAG, "Fetch config error", e)
                binding.fetchStatus.text = "Error fetching configuration: ${e.message}"
                Toast.makeText(this@RemoteConfigActivity, "Error: ${e.message}", Toast.LENGTH_LONG).show()
            }
        }
    }

    private fun updateConnectionStatus(connected: Boolean, message: String) {
        binding.connectionStatus.text = message
        binding.connectionStatus.setTextColor(
            getColor(if (connected) R.color.success else R.color.error)
        )
        binding.fetchConfigButton.isEnabled = connected
    }

    override fun onSupportNavigateUp(): Boolean {
        onBackPressed()
        return true
    }
}

package com.mifare.encoder

import android.app.PendingIntent
