class UserModeActivity : AppCompatActivity() {

    private lateinit var binding: ActivityUserModeBinding
    private var nfcAdapter: NfcAdapter? = null
    private var pendingIntent: PendingIntent? = null
    private var intentFilters: Array<IntentFilter>? = null
    private var techLists: Array<Array<String>>? = null
    private lateinit var authManager: AuthManager
    private var apiClient: ApiClient? = null

    companion object {
        private const val TAG = "UserModeActivity"
        private const val ADMIN_GESTURE_CLICKS = 7
        private var logoClickCount = 0
        private var lastClickTime = 0L
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        binding = ActivityUserModeBinding.inflate(layoutInflater)
        setContentView(binding.root)

        authManager = AuthManager.getInstance(this)

        setupNFC()
        setupUI()
        loadBackendConfig()
    }

    private fun setupNFC() {
        nfcAdapter = NfcAdapter.getDefaultAdapter(this)

        if (nfcAdapter == null) {
            showError("This device does not support NFC")
            return
        }

        if (!nfcAdapter!!.isEnabled) {
            showError("NFC is disabled. Please enable NFC in settings")
            return
        }

        pendingIntent = PendingIntent.getActivity(
            this, 0,
            Intent(this, javaClass).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP),
            PendingIntent.FLAG_MUTABLE
        )

        val mifareFilter = IntentFilter(NfcAdapter.ACTION_TECH_DISCOVERED)
        intentFilters = arrayOf(mifareFilter)
        techLists = arrayOf(arrayOf(MifareClassic::class.java.name))
    }

    private fun setupUI() {
        // Hidden admin access gesture - 7 quick clicks on logo
        binding.logoImageView.setOnClickListener {
            val currentTime = System.currentTimeMillis()

            if (currentTime - lastClickTime < 500) { // Within 500ms
                logoClickCount++
            } else {
                logoClickCount = 1
            }

            lastClickTime = currentTime

            if (logoClickCount >= ADMIN_GESTURE_CLICKS) {
                logoClickCount = 0
                showAdminPasswordDialog()
            }
        }

        // Simple status display
        updateStatus("Ready to program cards")
        binding.progressBar.visibility = View.GONE

        // Distribution link input handling
        val editTextLink: EditText = findViewById(R.id.editTextDistributionLink)
        val buttonSubmit: Button = findViewById(R.id.buttonSubmitLink)

        buttonSubmit.setOnClickListener {
            val link = editTextLink.text.toString().trim()
            if (link.isEmpty()) {
                Toast.makeText(this, "Please enter a valid link", Toast.LENGTH_SHORT).show()
                return@setOnClickListener
            }
            // Validate link format - check if it contains expected patterns
            if (!link.contains("/program/") && link.length < 20) {
                Toast.makeText(this, "Invalid distribution link format", Toast.LENGTH_SHORT).show()
                return@setOnClickListener
            }
            processDistributionLink(link)
        }
    }

    private fun loadBackendConfig() {
        // SECURITY FIX: Ensure app-wide migration and load from encrypted storage only
        try {
            val masterKey = androidx.security.crypto.MasterKey.Builder(this)
                .setKeyScheme(androidx.security.crypto.MasterKey.KeyScheme.AES256_GCM)
                .build()

            val securePrefs = androidx.security.crypto.EncryptedSharedPreferences.create(
                this,
                "admin_config_secure",
                masterKey,
                androidx.security.crypto.EncryptedSharedPreferences.PrefKeyEncryptionScheme.AES256_SIV,
                androidx.security.crypto.EncryptedSharedPreferences.PrefValueEncryptionScheme.AES256_GCM
            )

            // Migration handled globally by MifareApplication.onCreate()

            val backendUrl = securePrefs.getString("user_mode_url", "http://10.0.2.2:5000") // Default for emulator
            val apiKey = securePrefs.getString("user_mode_api_key", "user-mode-key")

            if (!backendUrl.isNullOrEmpty()) {
                apiClient = ApiClient(backendUrl, apiKey ?: "")
                Log.d(TAG, "Backend configured securely: $backendUrl")
            }
        } catch (e: Exception) {
            Log.e(TAG, "Failed to load secure backend config", e)
            // Fallback to default config for user mode
            apiClient = ApiClient("http://10.0.2.2:5000", "user-mode-key")
        }
    }


    override fun onResume() {
        super.onResume()
        nfcAdapter?.enableForegroundDispatch(this, pendingIntent, intentFilters, techLists)
    }

    override fun onPause() {
        super.onPause()
        nfcAdapter?.disableForegroundDispatch(this)
    }

    override fun onNewIntent(intent: Intent?) {
        super.onNewIntent(intent)
        intent?.let { handleNfcIntent(it) }
    }

    private fun handleNfcIntent(intent: Intent) {
        val tag = intent.getParcelableExtra<Tag>(NfcAdapter.EXTRA_TAG) ?: return

        updateStatus("Card detected...")
        binding.progressBar.visibility = View.VISIBLE

        lifecycleScope.launch {
            try {
                val mifareCard = MifareClassic.get(tag)
                if (mifareCard != null) {
                    programCard(mifareCard)
                } else {
                    showError("Unsupported card type")
                }
            } catch (e: Exception) {
                Log.e(TAG, "NFC handling error", e)
                showError("Card operation failed")
            } finally {
                binding.progressBar.visibility = View.GONE
            }
        }
    }

    private suspend fun programCard(mifareCard: MifareClassic) {
        try {
            updateStatus("Connecting to card...")
            mifareCard.connect()

            // Get device/user identifier for backend request
            val deviceId = android.provider.Settings.Secure.getString(
                contentResolver, 
                android.provider.Settings.Secure.ANDROID_ID
            )

            updateStatus("Fetching configuration...")

            // Automatic configuration fetch from backend
            val config = fetchUserConfiguration(deviceId)
            if (config == null) {
                showError("No programming data available. Contact admin.")
                return
            }

            updateStatus("Programming card...")

            // Program the card with fetched configuration
            val success = MifareUtils.writeCardData(mifareCard, config)

            if (success) {
                updateStatus("Programming complete!")
                showSuccess("Card programmed successfully")

                // Report success to backend
                apiClient?.submitProgrammingResult(
                    userId = config["userId"] ?: "unknown",
                    cardUid = MifareUtils.bytesToHex(mifareCard.tag.id),
                    success = true
                )
            } else {
                showError("Programming failed. Please try again.")
            }

        } catch (e: Exception) {
            Log.e(TAG, "Card programming error", e)
            showError("Programming error: ${e.message}")
        } finally {
            try {
                mifareCard.close()
            } catch (e: Exception) {
                Log.e(TAG, "Error closing card", e)
            }
        }
    }

    private suspend fun fetchUserConfiguration(deviceId: String): Map<String, String>? {
        return try {
            apiClient?.let { client ->
                val response = client.generateConfig(mapOf(
                    "deviceId" to deviceId,
                    "mode" to "user_auto"
                ))

                if (response.success && response.cardData.isNotEmpty()) {
                    // Parse the configuration from response
                    val configJson = String(android.util.Base64.decode(response.cardData, android.util.Base64.DEFAULT))
                    com.google.gson.Gson().fromJson(configJson, Map::class.java) as? Map<String, String>
                } else {
                    null
                }
            }
        } catch (e: Exception) {
            Log.e(TAG, "Failed to fetch user configuration", e)
            null
        }
    }

    private fun updateStatus(message: String) {
        runOnUiThread {
            binding.statusTextView.text = message
        }
    }

    private fun showError(message: String) {
        runOnUiThread {
            updateStatus("Error: $message")
            Toast.makeText(this, message, Toast.LENGTH_LONG).show()
        }
    }

    private fun showSuccess(message: String) {
        runOnUiThread {
            Toast.makeText(this, message, Toast.LENGTH_SHORT).show()
        }
    }

    private fun showAdminPasswordDialog() {
        val input = android.widget.EditText(this)
        input.inputType = android.text.InputType.TYPE_CLASS_TEXT or android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD

        AlertDialog.Builder(this)
            .setTitle("Admin Access")
            .setMessage("Enter admin password:")
            .setView(input)
            .setPositiveButton("Login") { _, _ ->
                val password = input.text.toString()
                if (authManager.authenticateAdmin(password)) {
                    // Switch to admin mode
                    startActivity(Intent(this, AdminModeActivity::class.java))
                    finish()
                } else {
                    Toast.makeText(this, "Invalid password", Toast.LENGTH_SHORT).show()
                }
            }
            .setNegativeButton("Cancel", null)
            .show()
    }

    private fun processDistributionLink(link: String) {
        CoroutineScope(Dispatchers.IO).launch {
            try {
                // Extract token from distribution link
                val token = if (link.contains("/program/")) {
                    link.substringAfter("/program/")
                } else {
                    link
                }

                // Retrieve user's Bearer token from shared preferences or existing auth system
                val sharedPref = getSharedPreferences("app_prefs", MODE_PRIVATE)
                val authToken = token // Use the distribution token directly for access

                if (authToken.isEmpty()) {
                    withContext(Dispatchers.Main) {
                        Toast.makeText(this@UserModeActivity, "Invalid distribution link", Toast.LENGTH_SHORT).show()
                    }
                    return@launch
                }

                val client = OkHttpClient()
                // Use existing backend API that accepts distribution tokens
                val backendUrl = "http://10.0.2.2:5000" // Default for emulator
                val request = Request.Builder()
                    .url("$backendUrl/api/android/programs")
                    .addHeader("Authorization", "Bearer $authToken")
                    .get()
                    .build()

                val response: Response = client.newCall(request).execute()
                if (response.isSuccessful) {
                    val responseBody = response.body?.string()
                    val json = JSONObject(responseBody ?: "{}")

                    if (json.getBoolean("success")) {
                        // Handle success: extract program data
                        val program = json.getJSONObject("program")
                        val programName = program.getString("name")
                        val programId = program.getString("id")

                        withContext(Dispatchers.Main) {
                            Toast.makeText(this@UserModeActivity, "Program accessed successfully: $programName", Toast.LENGTH_LONG).show()
                            updateStatus("Program loaded: $programName - Hold NFC card to phone")

                            // Store the program data for NFC programming
                            val sharedPrefs = getSharedPreferences("user_program", MODE_PRIVATE)
                            with(sharedPrefs.edit()) {
                                putString("current_program", responseBody)
                                putString("current_token", authToken)
                                apply()
                            }
                        }
                    } else {
                        val message = json.optString("message", "Unknown error")
                        withContext(Dispatchers.Main) {
                            Toast.makeText(this@UserModeActivity, "Failed to access program: $message", Toast.LENGTH_SHORT).show()
                        }
                    }
                } else {
                    withContext(Dispatchers.Main) {
                        Toast.makeText(this@UserModeActivity, "Failed to access: ${response.message}", Toast.LENGTH_SHORT).show()
                    }
                }
            } catch (e: Exception) {
                Log.e(TAG, "Distribution link processing error", e)
                withContext(Dispatchers.Main) {
                    Toast.makeText(this@UserModeActivity, "Error: ${e.message}", Toast.LENGTH_SHORT).show()
                }
            }
        }
    }
}

package com.mifare.encoder.adapters

import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.TextView
import androidx.recyclerview.widget.RecyclerView
import com.mifare.encoder.R
import com.mifare.encoder.models.CardData

class CardDataAdapter : RecyclerView.Adapter<RecyclerView.ViewHolder>() {

    private var cardData: CardData? = null

    companion object {
        private const val TYPE_HEADER = 0
        private const val TYPE_SECTOR = 1
        private const val TYPE_SALTO_DATA = 2
    }

    fun updateData(newCardData: CardData) {
        cardData = newCardData
        notifyDataSetChanged()
    }

    override fun getItemViewType(position: Int): Int {
        return when (position) {
            0 -> TYPE_HEADER
            in 1..(cardData?.sectors?.size ?: 0) -> TYPE_SECTOR
            else -> TYPE_SALTO_DATA
        }
    }

    override fun getItemCount(): Int {
        val card = cardData ?: return 0
        return 1 + card.sectors.size + if (card.saltoData != null) 1 else 0
    }

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): RecyclerView.ViewHolder {
        val inflater = LayoutInflater.from(parent.context)

        return when (viewType) {
            TYPE_HEADER -> {
                val view = inflater.inflate(R.layout.item_card_header, parent, false)
                HeaderViewHolder(view)
            }
            TYPE_SECTOR -> {
                val view = inflater.inflate(R.layout.item_sector_data, parent, false)
                SectorViewHolder(view)
            }
            TYPE_SALTO_DATA -> {
                val view = inflater.inflate(R.layout.item_salto_data, parent, false)
                SaltoDataViewHolder(view)
            }
            else -> throw IllegalArgumentException("Unknown view type: $viewType")
        }
    }

    override fun onBindViewHolder(holder: RecyclerView.ViewHolder, position: Int) {
        val card = cardData ?: return

        when (holder) {
            is HeaderViewHolder -> holder.bind(card)
            is SectorViewHolder -> {
                val sectorIndex = position - 1
                if (sectorIndex < card.sectors.size) {
                    holder.bind(card.sectors[sectorIndex])
                }
            }
            is SaltoDataViewHolder -> {
                card.saltoData?.let { holder.bind(it) }
            }
        }
    }

    class HeaderViewHolder(itemView: View) : RecyclerView.ViewHolder(itemView) {
        private val uidText: TextView = itemView.findViewById(R.id.uidText)
        private val typeText: TextView = itemView.findViewById(R.id.typeText)
        private val sizeText: TextView = itemView.findViewById(R.id.sizeText)

        fun bind(cardData: CardData) {
            uidText.text = "UID: ${cardData.uid}"
            typeText.text = "Type: ${cardData.type}"
            sizeText.text = "Size: ${cardData.size}"
        }
    }

    class SectorViewHolder(itemView: View) : RecyclerView.ViewHolder(itemView) {
        private val sectorText: TextView = itemView.findViewById(R.id.sectorText)

        fun bind(sectorData: String) {
            sectorText.text = sectorData
        }
    }

    class SaltoDataViewHolder(itemView: View) : RecyclerView.ViewHolder(itemView) {
        private val userIdText: TextView = itemView.findViewById(R.id.userIdText)
        private val accessRightsText: TextView = itemView.findViewById(R.id.accessRightsText)
        private val doorListText: TextView = itemView.findViewById(R.id.doorListText)
        private val timestampsText: TextView = itemView.findViewById(R.id.timestampsText)
        private val checksumText: TextView = itemView.findViewById(R.id.checksumText)
        private val validText: TextView = itemView.findViewById(R.id.validText)

        fun bind(saltoData: com.mifare.encoder.models.SaltoData) {
            userIdText.text = "User ID: ${saltoData.userId}"
            accessRightsText.text = "Access Rights: ${saltoData.accessRights.joinToString(", ")}"
            doorListText.text = "Doors: ${saltoData.doorList.joinToString(", ")}"
            timestampsText.text = "Valid: ${saltoData.startTimestamp} - ${saltoData.endTimestamp}"
            checksumText.text = "Checksum: ${saltoData.checksum}"
            validText.text = if (saltoData.isValid) "Valid Salto Data" else "Invalid/Unknown Format"
            validText.setTextColor(
                if (saltoData.isValid) 
                    itemView.context.getColor(R.color.success)
                else 
                    itemView.context.getColor(R.color.error)
            )
        }
    }
}

package com.mifare.encoder.fragments

import android.content.SharedPreferences
import android.os.Bundle
import android.util.Log
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.Toast
import androidx.fragment.app.Fragment
import androidx.lifecycle.lifecycleScope
import com.mifare.encoder.databinding.FragmentAdminConfigBinding
import com.mifare.encoder.utils.ApiClient
import com.mifare.encoder.utils.AuthManager
import kotlinx.coroutines.launch

class AdminConfigFragment : Fragment() {

    private var _binding: FragmentAdminConfigBinding? = null
    private val binding get() = _binding!!

    private lateinit var securePrefs: SharedPreferences
    private lateinit var authManager: AuthManager
    private var apiClient: ApiClient? = null

    companion object {
        private const val TAG = "AdminConfigFragment"
        private const val SECURE_PREFS_NAME = "admin_config_secure"
        private const val KEY_BACKEND_URL = "backend_url"
        private const val KEY_API_KEY = "api_key"
        private const val KEY_USER_MODE_URL = "user_mode_url"
        private const val KEY_USER_MODE_API_KEY = "user_mode_api_key"
    }

    override fun onCreateView(
        inflater: LayoutInflater,
        container: ViewGroup?,
        savedInstanceState: Bundle?
    ): View {
        _binding = FragmentAdminConfigBinding.inflate(inflater, container, false)
        return binding.root
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)

        // Use encrypted shared preferences for secure storage of API keys
        val masterKey = androidx.security.crypto.MasterKey.Builder(requireContext())
            .setKeyScheme(androidx.security.crypto.MasterKey.KeyScheme.AES256_GCM)
            .build()

        securePrefs = androidx.security.crypto.EncryptedSharedPreferences.create(
            requireContext(),
            SECURE_PREFS_NAME,
            masterKey,
            androidx.security.crypto.EncryptedSharedPreferences.PrefKeyEncryptionScheme.AES256_SIV,
            androidx.security.crypto.EncryptedSharedPreferences.PrefValueEncryptionScheme.AES256_GCM
        )

        authManager = AuthManager.getInstance(requireContext())

        setupUI()
        loadSavedConfig()
    }

    private fun setupUI() {
        // Backend Configuration
        binding.testConnectionButton.setOnClickListener {
            testBackendConnection()
        }

        binding.saveConfigButton.setOnClickListener {
            saveConfiguration()
        }

        binding.pushConfigButton.setOnClickListener {
            pushConfigurationToBackend()
        }

        // User Mode Configuration
        binding.saveUserConfigButton.setOnClickListener {
            saveUserModeConfiguration()
        }

        binding.testUserConnectionButton.setOnClickListener {
            testUserModeConnection()
        }

        // System Actions
        binding.changePasswordButton.setOnClickListener {
            showChangePasswordDialog()
        }

        binding.exportConfigButton.setOnClickListener {
            exportConfiguration()
        }

        binding.importConfigButton.setOnClickListener {
            showImportConfigDialog()
        }
    }

    private fun loadSavedConfig() {
        // Load admin backend config from encrypted storage
        val savedUrl = securePrefs.getString(KEY_BACKEND_URL, "http://10.0.2.2:5000")
        val savedApiKey = securePrefs.getString(KEY_API_KEY, "admin-api-key")

        binding.backendUrlEditText.setText(savedUrl)
        binding.apiKeyEditText.setText(savedApiKey)

        // Load user mode config from encrypted storage
        val userUrl = securePrefs.getString(KEY_USER_MODE_URL, "http://10.0.2.2:5000")
        val userApiKey = securePrefs.getString(KEY_USER_MODE_API_KEY, "user-mode-key")

        binding.userModeUrlEditText.setText(userUrl)
        binding.userModeApiKeyEditText.setText(userApiKey)

        if (!savedUrl.isNullOrEmpty() && !savedApiKey.isNullOrEmpty()) {
            updateConnectionStatus(true, "Saved configuration loaded")
        }
    }

    private fun saveConfiguration() {
        val url = binding.backendUrlEditText.text.toString().trim()
        val apiKey = binding.apiKeyEditText.text.toString().trim()

        if (url.isEmpty()) {
            showMessage("Backend URL is required")
            return
        }

        if (apiKey.isEmpty()) {
            showMessage("API key is required")
            return
        }

        securePrefs.edit()
            .putString(KEY_BACKEND_URL, url)
            .putString(KEY_API_KEY, apiKey)
            .apply()

        apiClient = ApiClient(url, apiKey)
        showMessage("Configuration saved")

        authManager.extendSession()
    }

    private fun saveUserModeConfiguration() {
        val url = binding.userModeUrlEditText.text.toString().trim()
        val apiKey = binding.userModeApiKeyEditText.text.toString().trim()

        // SECURITY FIX: Only save to encrypted preferences, remove plaintext storage
        securePrefs.edit()
            .putString(KEY_USER_MODE_URL, url)
            .putString(KEY_USER_MODE_API_KEY, apiKey)
            .apply()

        // Migrate any existing plaintext user config to secure storage
        migrateUserConfigToSecureStorage()

        showMessage("User mode configuration saved securely")
    }

    private fun migrateUserConfigToSecureStorage() {
        // One-time migration from plaintext to encrypted storage
        val userPrefs = requireContext().getSharedPreferences("user_config", android.content.Context.MODE_PRIVATE)
        val existingUrl = userPrefs.getString("backend_url", null)
        val existingApiKey = userPrefs.getString("api_key", null)

        if (!existingUrl.isNullOrEmpty() || !existingApiKey.isNullOrEmpty()) {
            // Migrate to secure storage
            securePrefs.edit()
                .putString(KEY_USER_MODE_URL, existingUrl ?: "")
                .putString(KEY_USER_MODE_API_KEY, existingApiKey ?: "")
                .apply()

            // Clear plaintext storage
            userPrefs.edit().clear().apply()

            android.util.Log.i(TAG, "Migrated user config from plaintext to encrypted storage")
        }
    }

    private fun testBackendConnection() {
        val url = binding.backendUrlEditText.text.toString().trim()
        val apiKey = binding.apiKeyEditText.text.toString().trim()

        if (url.isEmpty()) {
            showMessage("Enter backend URL first")
            return
        }

        updateConnectionStatus(false, "Testing connection...")

        lifecycleScope.launch {
            try {
                val testClient = ApiClient(url, apiKey)
                val response = testClient.testConnection()

                if (response.success) {
                    updateConnectionStatus(true, "Connected successfully")
                    apiClient = testClient
                    showMessage("Connection successful!")
                } else {
                    updateConnectionStatus(false, "Connection failed: ${response.message}")
                    showMessage("Connection failed: ${response.message}")
                }
            } catch (e: Exception) {
                Log.e(TAG, "Connection test error", e)
                updateConnectionStatus(false, "Connection error: ${e.message}")
                showMessage("Connection error: ${e.message}")
            }
        }
    }

    private fun testUserModeConnection() {
        val url = binding.userModeUrlEditText.text.toString().trim()
        val apiKey = binding.userModeApiKeyEditText.text.toString().trim()

        if (url.isEmpty()) {
            showMessage("Enter user mode URL first")
            return
        }

        binding.userConnectionStatus.text = "Testing user mode connection..."

        lifecycleScope.launch {
            try {
                val testClient = ApiClient(url, apiKey)
                val response = testClient.testConnection()

                if (response.success) {
                    binding.userConnectionStatus.text = "User mode connection successful"
                    binding.userConnectionStatus.setTextColor(resources.getColor(android.R.color.holo_green_dark, null))
                    showMessage("User mode connection successful!")
                } else {
                    binding.userConnectionStatus.text = "User mode connection failed: ${response.message}"
                    binding.userConnectionStatus.setTextColor(resources.getColor(android.R.color.holo_red_dark, null))
                }
            } catch (e: Exception) {
                Log.e(TAG, "User mode connection test error", e)
                binding.userConnectionStatus.text = "User mode connection error: ${e.message}"
                binding.userConnectionStatus.setTextColor(resources.getColor(android.R.color.holo_red_dark, null))
            }
        }
    }

    private fun pushConfigurationToBackend() {
        if (apiClient == null) {
            showMessage("Please test connection first")
            return
        }

        val config = mapOf(
            "deviceId" to android.provider.Settings.Secure.getString(
                requireContext().contentResolver,
                android.provider.Settings.Secure.ANDROID_ID
            ),
            "deviceType" to "admin_device",
            "configVersion" to "1.0",
            "userModeUrl" to binding.userModeUrlEditText.text.toString(),
            "capabilities" to "scan,write,admin",
            "timestamp" to System.currentTimeMillis().toString()
        )

        lifecycleScope.launch {
            try {
                val response = apiClient!!.generateConfig(config)

                if (response.success) {
                    showMessage("Configuration pushed to backend")
                    binding.pushStatus.text = "Last push: ${java.text.SimpleDateFormat("HH:mm:ss", java.util.Locale.getDefault()).format(java.util.Date())}"
                } else {
                    showMessage("Failed to push configuration: ${response.message}")
                    binding.pushStatus.text = "Push failed: ${response.message}"
                }
            } catch (e: Exception) {
                Log.e(TAG, "Push config error", e)
                showMessage("Push error: ${e.message}")
                binding.pushStatus.text = "Push error: ${e.message}"
            }
        }
    }

    private fun showChangePasswordDialog() {
        val input = android.widget.EditText(requireContext())
        input.inputType = android.text.InputType.TYPE_CLASS_TEXT or android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD
        input.hint = "New admin password"

        androidx.appcompat.app.AlertDialog.Builder(requireContext())
            .setTitle("Change Admin Password")
            .setMessage("Enter new password (minimum 8 characters):")
            .setView(input)
            .setPositiveButton("Change") { _, _ ->
                val newPassword = input.text.toString()
                if (newPassword.length >= 8) {
                    authManager.setAdminPassword(newPassword)
                    showMessage("Password updated successfully")
                } else {
                    showMessage("Password must be at least 8 characters")
                }
            }
            .setNegativeButton("Cancel", null)
            .show()
    }

    private fun exportConfiguration() {
        val config = buildString {
            append("MIFARE Admin Configuration Export\n")
            append("Generated: ${java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss", java.util.Locale.getDefault()).format(java.util.Date())}\n")
            append("="*40 + "\n\n")

            append("Backend Configuration:\n")
            append("URL: ${binding.backendUrlEditText.text}\n")
            append("API Key: ${binding.apiKeyEditText.text.toString().take(8)}...\n\n")

            append("User Mode Configuration:\n")
            append("URL: ${binding.userModeUrlEditText.text}\n")
            append("API Key: ${binding.userModeApiKeyEditText.text.toString().take(8)}...\n\n")

            append("Device Information:\n")
            append("Device ID: ${android.provider.Settings.Secure.getString(requireContext().contentResolver, android.provider.Settings.Secure.ANDROID_ID)}\n")
            append("Android Version: ${android.os.Build.VERSION.RELEASE}\n")
            append("Model: ${android.os.Build.MODEL}\n")
        }

        val clipboard = requireContext().getSystemService(android.content.Context.CLIPBOARD_SERVICE) as android.content.ClipboardManager
        val clip = android.content.ClipData.newPlainText("Admin Config", config)
        clipboard.setPrimaryClip(clip)

        showMessage("Configuration exported to clipboard")
    }

    private fun showImportConfigDialog() {
        val input = android.widget.EditText(requireContext())
        input.hint = "Paste configuration data here"
        input.inputType = android.text.InputType.TYPE_CLASS_TEXT or android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE
        input.minLines = 3

        androidx.appcompat.app.AlertDialog.Builder(requireContext())
            .setTitle("Import Configuration")
            .setMessage("Paste exported configuration:")
            .setView(input)
            .setPositiveButton("Import") { _, _ ->
                val configData = input.text.toString()
                // Simple parsing - in production would use JSON
                if (configData.contains("Backend Configuration:")) {
                    showMessage("Configuration import placeholder - feature coming soon")
                } else {
                    showMessage("Invalid configuration format")
                }
            }
            .setNegativeButton("Cancel", null)
            .show()
    }

    private fun updateConnectionStatus(connected: Boolean, message: String) {
        binding.connectionStatus.text = message
        binding.connectionStatus.setTextColor(
            resources.getColor(
                if (connected) android.R.color.holo_green_dark else android.R.color.holo_red_dark,
                null
            )
        )
        binding.pushConfigButton.isEnabled = connected
    }

    private fun showMessage(message: String) {
        Toast.makeText(requireContext(), message, Toast.LENGTH_SHORT).show()
    }

    override fun onDestroyView() {
        super.onDestroyView()
        _binding = null
    }
}

package com.mifare.encoder.fragments

import android.os.Bundle
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.Toast
import androidx.fragment.app.Fragment
import com.mifare.encoder.databinding.FragmentAdminLogsBinding
import com.mifare.encoder.utils.AuthManager

class AdminLogsFragment : Fragment() {

    private var _binding: FragmentAdminLogsBinding? = null
    private val binding get() = _binding!!

    private lateinit var authManager: AuthManager

    companion object {
        private const val TAG = "AdminLogsFragment"
    }

    override fun onCreateView(
        inflater: LayoutInflater,
        container: ViewGroup?,
        savedInstanceState: Bundle?
    ): View {
        _binding = FragmentAdminLogsBinding.inflate(inflater, container, false)
        return binding.root
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)

        authManager = AuthManager.getInstance(requireContext())

        setupUI()
        refreshLogs()
    }

    private fun setupUI() {
        binding.refreshButton.setOnClickListener {
            refreshLogs()
        }

        binding.clearLogsButton.setOnClickListener {
            showClearLogsDialog()
        }

        binding.exportLogsButton.setOnClickListener {
            exportLogs()
        }

        binding.systemInfoButton.setOnClickListener {
            showSystemInfo()
        }
    }

    fun refreshLogs() {
        val logs = authManager.getAdminLogs()

        binding.logsTextView.text = if (logs.isNotEmpty()) {
            logs
        } else {
            "No admin activity logged yet.\n\nAdmin actions will appear here including:\n" +
                    "- Authentication events\n" +
                    "- Mode switches\n" +
                    "- Password changes\n" +
                    "- Configuration updates\n" +
                    "- Card operations\n"
        }

        // Update status
        val logLines = logs.split("\n").filter { it.isNotBlank() }
        binding.logCountText.text = "Log entries: ${logLines.size}"

        binding.lastRefreshText.text = "Last refresh: ${
            java.text.SimpleDateFormat("HH:mm:ss", java.util.Locale.getDefault())
                .format(java.util.Date())
        }"
    }

    private fun showClearLogsDialog() {
        androidx.appcompat.app.AlertDialog.Builder(requireContext())
            .setTitle("Clear Admin Logs")
            .setMessage("This will permanently delete all admin activity logs. This action cannot be undone.\n\nContinue?")
            .setPositiveButton("Clear Logs") { _, _ ->
                authManager.clearAdminLogs()
                refreshLogs()
                showMessage("Admin logs cleared")
            }
            .setNegativeButton("Cancel", null)
            .show()
    }

    private fun exportLogs() {
        val logs = authManager.getAdminLogs()

        if (logs.isBlank()) {
            showMessage("No logs to export")
            return
        }

        val exportData = buildString {
            append("MIFARE Admin Logs Export\n")
            append("Generated: ${
                java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss", java.util.Locale.getDefault())
                    .format(java.util.Date())
            }\n")
            append("Device ID: ${
                android.provider.Settings.Secure.getString(
                    requireContext().contentResolver,
                    android.provider.Settings.Secure.ANDROID_ID
                )
            }\n")
            append("="*50 + "\n\n")
            append(logs)
            append("\n\n" + "="*50)
            append("\nEnd of admin logs export")
        }

        val clipboard = requireContext().getSystemService(android.content.Context.CLIPBOARD_SERVICE) as android.content.ClipboardManager
        val clip = android.content.ClipData.newPlainText("Admin Logs", exportData)
        clipboard.setPrimaryClip(clip)

        showMessage("Admin logs exported to clipboard")
    }

    private fun showSystemInfo() {
        val systemInfo = buildString {
            append("=== SYSTEM INFORMATION ===\n\n")

            append("Device Information:\n")
            append("Device ID: ${
                android.provider.Settings.Secure.getString(
                    requireContext().contentResolver,
                    android.provider.Settings.Secure.ANDROID_ID
                )
            }\n")
            append("Model: ${android.os.Build.MODEL}\n")
            append("Manufacturer: ${android.os.Build.MANUFACTURER}\n")
            append("Android Version: ${android.os.Build.VERSION.RELEASE}\n")
            append("API Level: ${android.os.Build.VERSION.SDK_INT}\n")
            append("Build: ${android.os.Build.DISPLAY}\n\n")

            append("NFC Information:\n")
            val nfcAdapter = android.nfc.NfcAdapter.getDefaultAdapter(requireContext())
            if (nfcAdapter != null) {
                append("NFC Supported: Yes\n")
                append("NFC Enabled: ${if (nfcAdapter.isEnabled) "Yes" else "No"}\n")
            } else {
                append("NFC Supported: No\n")
            }
            append("\n")

            append("App Information:\n")
            try {
                val packageInfo = requireContext().packageManager.getPackageInfo(requireContext().packageName, 0)
                append("Version: ${packageInfo.versionName}\n")
                append("Version Code: ${packageInfo.versionCode}\n")
            } catch (e: Exception) {
                append("Version: Unable to retrieve\n")
            }
            append("Package: ${requireContext().packageName}\n")
            append("Admin Mode: ${if (authManager.isAdminMode()) "Active" else "Inactive"}\n\n")

            append("Memory Information:\n")
            val runtime = Runtime.getRuntime()
            val totalMemory = runtime.totalMemory() / (1024 * 1024)
            val freeMemory = runtime.freeMemory() / (1024 * 1024)
            val usedMemory = totalMemory - freeMemory
            val maxMemory = runtime.maxMemory() / (1024 * 1024)

            append("Total Memory: ${totalMemory}MB\n")
            append("Used Memory: ${usedMemory}MB\n")
            append("Free Memory: ${freeMemory}MB\n")
            append("Max Memory: ${maxMemory}MB\n\n")

            append("Security Information:\n")
            append("Admin Session Active: ${authManager.isAdminMode()}\n")
            append("Logs Available: ${authManager.getAdminLogs().isNotBlank()}\n")
            append("Timestamp: ${System.currentTimeMillis()}\n")
        }

        androidx.appcompat.app.AlertDialog.Builder(requireContext())
            .setTitle("System Information")
            .setMessage(systemInfo)
            .setPositiveButton("Close", null)
            .setNeutralButton("Copy") { _, _ ->
                val clipboard = requireContext().getSystemService(android.content.Context.CLIPBOARD_SERVICE) as android.content.ClipboardManager
                val clip = android.content.ClipData.newPlainText("System Info", systemInfo)
                clipboard.setPrimaryClip(clip)
                showMessage("System information copied to clipboard")
            }
            .show()
    }

    private fun showMessage(message: String) {
        Toast.makeText(requireContext(), message, Toast.LENGTH_SHORT).show()
    }

    override fun onDestroyView() {
        super.onDestroyView()
        _binding = null
    }
}

package com.mifare.encoder.fragments

import android.app.PendingIntent
import android.content.Intent
import android.content.IntentFilter
import android.nfc.NfcAdapter
import android.nfc.Tag
import android.nfc.tech.MifareClassic
import android.os.Bundle
import android.util.Log
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.Toast
import androidx.fragment.app.Fragment
import androidx.lifecycle.lifecycleScope
import androidx.recyclerview.widget.LinearLayoutManager
import com.mifare.encoder.R
import com.mifare.encoder.adapters.CardDataAdapter
import com.mifare.encoder.databinding.FragmentAdminScanBinding
import com.mifare.encoder.models.CardData
import com.mifare.encoder.utils.MifareUtils
import com.mifare.encoder.utils.SaltoProtocol
import kotlinx.coroutines.launch

class AdminScanFragment : Fragment() {

    private var _binding: FragmentAdminScanBinding? = null
    private val binding get() = _binding!!

    private var nfcAdapter: NfcAdapter? = null
    private var pendingIntent: PendingIntent? = null
    private var intentFilters: Array<IntentFilter>? = null
    private var techLists: Array<Array<String>>? = null

    private lateinit var cardDataAdapter: CardDataAdapter
    private val scannedCards = mutableListOf<CardData>()

    companion object {
        private const val TAG = "AdminScanFragment"
    }

    override fun onCreateView(
        inflater: LayoutInflater,
        container: ViewGroup?,
        savedInstanceState: Bundle?
    ): View {
        _binding = FragmentAdminScanBinding.inflate(inflater, container, false)
        return binding.root
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)

        setupNFC()
        setupRecyclerView()
        setupUI()
    }

    private fun setupNFC() {
        nfcAdapter = NfcAdapter.getDefaultAdapter(requireContext())

        if (nfcAdapter == null) {
            showMessage("NFC not supported on this device")
            return
        }

        pendingIntent = PendingIntent.getActivity(
            requireContext(), 0,
            Intent(requireContext(), requireActivity().javaClass).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP),
            PendingIntent.FLAG_MUTABLE
        )

        val mifareFilter = IntentFilter(NfcAdapter.ACTION_TECH_DISCOVERED)
        intentFilters = arrayOf(mifareFilter)
        techLists = arrayOf(arrayOf(MifareClassic::class.java.name))
    }

    /**
     * Handle NFC intent forwarded from AdminModeActivity
     */
    fun handleNfcIntent(intent: Intent) {
        val tag = intent.getParcelableExtra<Tag>(NfcAdapter.EXTRA_TAG)
        tag?.let { processNfcTag(it) }
    }

    private fun setupRecyclerView() {
        cardDataAdapter = CardDataAdapter(scannedCards) { cardData ->
            showCardDetails(cardData)
        }

        binding.recyclerView.apply {
            layoutManager = LinearLayoutManager(requireContext())
            adapter = cardDataAdapter
        }
    }

    private fun setupUI() {
        binding.scanButton.setOnClickListener {
            if (nfcAdapter?.isEnabled == true) {
                showMessage("Ready to scan. Hold card near device...")
                binding.statusText.text = "Waiting for NFC card..."
            } else {
                showMessage("Please enable NFC in device settings")
            }
        }

        binding.clearButton.setOnClickListener {
            scannedCards.clear()
            cardDataAdapter.notifyDataSetChanged()
            binding.statusText.text = "Scan history cleared"
        }

        binding.exportButton.setOnClickListener {
            exportScanData()
        }
    }

    override fun onResume() {
        super.onResume()
        nfcAdapter?.enableForegroundDispatch(
            requireActivity(),
            pendingIntent,
            intentFilters,
            techLists
        )
    }

    override fun onPause() {
        super.onPause()
        nfcAdapter?.disableForegroundDispatch(requireActivity())
    }

    fun handleNfcIntent(intent: Intent) {
        val tag = intent.getParcelableExtra<Tag>(NfcAdapter.EXTRA_TAG) ?: return

        binding.statusText.text = "Processing card..."

        lifecycleScope.launch {
            try {
                val cardData = scanCard(tag)
                if (cardData != null) {
                    scannedCards.add(0, cardData) // Add to top
                    cardDataAdapter.notifyItemInserted(0)
                    binding.recyclerView.scrollToPosition(0)

                    binding.statusText.text = "Card scanned successfully (${cardData.cardType})"
                    showMessage("Card data decoded and added to list")
                } else {
                    binding.statusText.text = "Failed to read card data"
                    showMessage("Unable to read card. Check card type.")
                }
            } catch (e: Exception) {
                Log.e(TAG, "Card scan error", e)
                binding.statusText.text = "Scan error: ${e.message}"
                showMessage("Error scanning card: ${e.message}")
            }
        }
    }

    private suspend fun scanCard(tag: Tag): CardData? {
        val mifareCard = MifareClassic.get(tag) ?: return null

        return try {
            mifareCard.connect()

            val uid = MifareUtils.bytesToHex(tag.id)
            val cardType = when (mifareCard.type) {
                MifareClassic.TYPE_CLASSIC -> "MIFARE Classic 1K"
                MifareClassic.TYPE_PLUS -> "MIFARE Plus"
                MifareClassic.TYPE_PRO -> "MIFARE Pro"
                else -> "MIFARE Classic ${mifareCard.size} bytes"
            }

            // Read all accessible sectors
            val sectorData = mutableMapOf<Int, String>()
            val rawHexData = StringBuilder()

            for (sectorIndex in 0 until mifareCard.sectorCount) {
                try {
                    if (mifareCard.authenticateSectorWithKeyA(sectorIndex, MifareClassic.KEY_DEFAULT)) {
                        val blockCount = mifareCard.getBlockCountInSector(sectorIndex)
                        val sectorStart = mifareCard.sectorToBlock(sectorIndex)

                        val sectorHex = StringBuilder()
                        for (blockIndex in 0 until blockCount) {
                            val blockData = mifareCard.readBlock(sectorStart + blockIndex)
                            val hexData = MifareUtils.bytesToHex(blockData)
                            sectorHex.append("Block ${sectorStart + blockIndex}: $hexData\n")
                            rawHexData.append(hexData)
                        }

                        sectorData[sectorIndex] = sectorHex.toString()
                    } else {
                        sectorData[sectorIndex] = "Authentication failed (custom keys)"
                    }
                } catch (e: Exception) {
                    sectorData[sectorIndex] = "Read error: ${e.message}"
                }
            }

            // Analyze for Salto protocol
            val saltoAnalysis = SaltoProtocol.analyzeCardData(rawHexData.toString())

            CardData(
                uid = uid,
                cardType = cardType,
                timestamp = System.currentTimeMillis(),
                sectorData = sectorData,
                saltoData = saltoAnalysis,
                rawHexData = rawHexData.toString()
            )

        } catch (e: Exception) {
            Log.e(TAG, "Error reading card", e)
            null
        } finally {
            try {
                mifareCard.close()
            } catch (e: Exception) {
                Log.e(TAG, "Error closing card", e)
            }
        }
    }

    private fun showCardDetails(cardData: CardData) {
        val details = buildString {
            append("Card UID: ${cardData.uid}\n")
            append("Type: ${cardData.cardType}\n")
            append("Scanned: ${java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss", java.util.Locale.getDefault()).format(java.util.Date(cardData.timestamp))}\n\n")

            append("=== SECTOR DATA ===\n")
            cardData.sectorData.forEach { (sector, data) ->
                append("Sector $sector:\n$data\n")
            }

            append("\n=== SALTO ANALYSIS ===\n")
            if (cardData.saltoData != null) {
                append("User ID: ${cardData.saltoData.userId ?: "Unknown"}\n")
                append("Access Doors: ${cardData.saltoData.accessDoors?.joinToString(", ") ?: "None"}\n")
                append("Valid From: ${cardData.saltoData.validFrom ?: "Unknown"}\n")
                append("Valid Until: ${cardData.saltoData.validUntil ?: "Unknown"}\n")
                append("Card Status: ${cardData.saltoData.cardStatus ?: "Unknown"}\n")
                append("Issuer ID: ${cardData.saltoData.issuerId ?: "Unknown"}\n")
            } else {
                append("No Salto protocol data detected\n")
            }

            append("\n=== RAW HEX DATA ===\n")
            append(cardData.rawHexData.chunked(32).joinToString("\n"))
        }

        androidx.appcompat.app.AlertDialog.Builder(requireContext())
            .setTitle("Card Details: ${cardData.uid}")
            .setMessage(details)
            .setPositiveButton("Close", null)
            .setNeutralButton("Copy") { _, _ ->
                val clipboard = requireContext().getSystemService(android.content.Context.CLIPBOARD_SERVICE) as android.content.ClipboardManager
                val clip = android.content.ClipData.newPlainText("Card Data", details)
                clipboard.setPrimaryClip(clip)
                showMessage("Card data copied to clipboard")
            }
            .show()
    }

    private fun exportScanData() {
        if (scannedCards.isEmpty()) {
            showMessage("No scan data to export")
            return
        }

        val exportData = buildString {
            append("MIFARE Card Scan Export\n")
            append("Generated: ${java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss", java.util.Locale.getDefault()).format(java.util.Date())}\n")
            append("Total Cards: ${scannedCards.size}\n")
            append("="*50 + "\n\n")

            scannedCards.forEachIndexed { index, card ->
                append("Card ${index + 1}: ${card.uid}\n")
                append("Type: ${card.cardType}\n")
                append("Timestamp: ${java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss", java.util.Locale.getDefault()).format(java.util.Date(card.timestamp))}\n")

                if (card.saltoData != null) {
                    append("Salto User ID: ${card.saltoData.userId}\n")
                    append("Access Doors: ${card.saltoData.accessDoors?.joinToString(", ")}\n")
                }

                append("Raw Data: ${card.rawHexData.take(100)}...\n")
                append("-"*30 + "\n\n")
            }
        }

        // Copy to clipboard for now (could be enhanced to save to file)
        val clipboard = requireContext().getSystemService(android.content.Context.CLIPBOARD_SERVICE) as android.content.ClipboardManager
        val clip = android.content.ClipData.newPlainText("Scan Export", exportData)
        clipboard.setPrimaryClip(clip)

        showMessage("Scan data exported to clipboard")
    }

    private fun showMessage(message: String) {
        Toast.makeText(requireContext(), message, Toast.LENGTH_SHORT).show()
    }

    override fun onDestroyView() {
        super.onDestroyView()
        _binding = null
    }
}

package com.mifare.encoder.fragments

import android.app.PendingIntent
import android.content.Intent
import android.content.IntentFilter
import android.nfc.NfcAdapter
import android.nfc.Tag
import android.nfc.tech.MifareClassic
import android.os.Bundle
import android.util.Log
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.Toast
import androidx.fragment.app.Fragment
import androidx.lifecycle.lifecycleScope
import com.mifare.encoder.databinding.FragmentAdminWriteBinding
import com.mifare.encoder.utils.MifareUtils
import com.mifare.encoder.utils.SaltoProtocol
import kotlinx.coroutines.launch

class AdminWriteFragment : Fragment() {

    private var _binding: FragmentAdminWriteBinding? = null
    private val binding get() = _binding!!

    private var nfcAdapter: NfcAdapter? = null
    private var pendingIntent: PendingIntent? = null
    private var intentFilters: Array<IntentFilter>? = null
    private var techLists: Array<Array<String>>? = null

    private var isWriteModeEnabled = false

    companion object {
        private const val TAG = "AdminWriteFragment"
    }

    override fun onCreateView(
        inflater: LayoutInflater,
        container: ViewGroup?,
        savedInstanceState: Bundle?
    ): View {
        _binding = FragmentAdminWriteBinding.inflate(inflater, container, false)
        return binding.root
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)

        setupNFC()
        setupUI()
        loadDefaultValues()
    }

    private fun setupNFC() {
        nfcAdapter = NfcAdapter.getDefaultAdapter(requireContext())

        if (nfcAdapter == null) {
            showMessage("NFC not supported on this device")
            binding.writeButton.isEnabled = false
            return
        }

        pendingIntent = PendingIntent.getActivity(
            requireContext(), 0,
            Intent(requireContext(), requireActivity().javaClass).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP),
            PendingIntent.FLAG_MUTABLE
        )

        val mifareFilter = IntentFilter(NfcAdapter.ACTION_TECH_DISCOVERED)
        intentFilters = arrayOf(mifareFilter)
        techLists = arrayOf(arrayOf(MifareClassic::class.java.name))
    }

    /**
     * Handle NFC intent forwarded from AdminModeActivity
     */
    fun handleNfcIntent(intent: Intent) {
        val tag = intent.getParcelableExtra<Tag>(NfcAdapter.EXTRA_TAG)
        tag?.let { processNfcWrite(it) }
    }

    private fun setupUI() {
        binding.writeButton.setOnClickListener {
            if (validateInputs()) {
                enableWriteMode()
            }
        }

        binding.generateButton.setOnClickListener {
            generateSampleData()
        }

        binding.previewButton.setOnClickListener {
            previewCardData()
        }

        binding.resetButton.setOnClickListener {
            resetForm()
        }

        // Date picker setup for start/end dates
        binding.startDateEditText.setOnClickListener {
            showDatePicker { date ->
                binding.startDateEditText.setText(date)
            }
        }

        binding.endDateEditText.setOnClickListener {
            showDatePicker { date ->
                binding.endDateEditText.setText(date)
            }
        }
    }

    private fun loadDefaultValues() {
        // Load some example values
        binding.userIdEditText.setText("12345")
        binding.accessDoorsEditText.setText("101,102,103,201")
        binding.startDateEditText.setText("2025-01-01T08:00:00Z")
        binding.endDateEditText.setText("2025-12-31T18:00:00Z")
        binding.accessLevelSpinner.setSelection(0) // Guest
        binding.notesEditText.setText("Admin generated key")
    }

    private fun validateInputs(): Boolean {
        val userId = binding.userIdEditText.text.toString().trim()
        val doors = binding.accessDoorsEditText.text.toString().trim()
        val startDate = binding.startDateEditText.text.toString().trim()
        val endDate = binding.endDateEditText.text.toString().trim()

        if (userId.isEmpty()) {
            showMessage("User ID is required")
            return false
        }

        if (doors.isEmpty()) {
            showMessage("Access doors are required")
            return false
        }

        if (startDate.isEmpty() || endDate.isEmpty()) {
            showMessage("Start and end dates are required")
            return false
        }

        // Validate date format
        try {
            java.time.Instant.parse(startDate)
            java.time.Instant.parse(endDate)
        } catch (e: Exception) {
            showMessage("Invalid date format. Use ISO format: YYYY-MM-DDTHH:MM:SSZ")
            return false
        }

        return true
    }

    private fun enableWriteMode() {
        isWriteModeEnabled = true
        binding.statusText.text = "Write mode enabled. Hold card near device to program..."
        binding.statusText.setBackgroundColor(resources.getColor(android.R.color.holo_orange_light, null))
        binding.writeButton.text = "Cancel Write"
        binding.writeButton.setOnClickListener {
            disableWriteMode()
        }

        showMessage("Ready to write. Hold MIFARE card near device.")
    }

    private fun disableWriteMode() {
        isWriteModeEnabled = false
        binding.statusText.text = "Write mode disabled"
        binding.statusText.setBackgroundColor(resources.getColor(android.R.color.transparent, null))
        binding.writeButton.text = "Write to Card"
        binding.writeButton.setOnClickListener {
            if (validateInputs()) {
                enableWriteMode()
            }
        }
    }

    override fun onResume() {
        super.onResume()
        if (isWriteModeEnabled) {
            nfcAdapter?.enableForegroundDispatch(
                requireActivity(),
                pendingIntent,
                intentFilters,
                techLists
            )
        }
    }

    override fun onPause() {
        super.onPause()
        nfcAdapter?.disableForegroundDispatch(requireActivity())
    }

    fun handleNfcIntent(intent: Intent) {
        if (!isWriteModeEnabled) return

        val tag = intent.getParcelableExtra<Tag>(NfcAdapter.EXTRA_TAG) ?: return

        binding.statusText.text = "Programming card..."

        lifecycleScope.launch {
            try {
                val success = writeCardData(tag)
                if (success) {
                    binding.statusText.text = "Card programmed successfully!"
                    binding.statusText.setBackgroundColor(resources.getColor(android.R.color.holo_green_light, null))
                    showMessage("Card programming completed successfully")
                } else {
                    binding.statusText.text = "Programming failed. Check card and try again."
                    binding.statusText.setBackgroundColor(resources.getColor(android.R.color.holo_red_light, null))
                    showMessage("Programming failed. Please try again.")
                }

                disableWriteMode()

            } catch (e: Exception) {
                Log.e(TAG, "Card write error", e)
                binding.statusText.text = "Write error: ${e.message}"
                binding.statusText.setBackgroundColor(resources.getColor(android.R.color.holo_red_light, null))
                showMessage("Error: ${e.message}")
                disableWriteMode()
            }
        }
    }

    private suspend fun writeCardData(tag: Tag): Boolean {
        val mifareCard = MifareClassic.get(tag) ?: return false

        return try {
            mifareCard.connect()

            // Generate card data based on form inputs
            val cardData = generateCardConfiguration()

            // Write to card using MifareUtils
            val writeSuccess = MifareUtils.writeCardData(mifareCard, cardData)

            if (writeSuccess) {
                Log.d(TAG, "Card programming successful")

                // Log the programming action with details
                val uid = MifareUtils.bytesToHex(tag.id)
                Log.i(TAG, "Card programmed - UID: $uid, User: ${cardData["userId"]}, Doors: ${cardData["doors"]}")
            }

            writeSuccess

        } catch (e: Exception) {
            Log.e(TAG, "Error writing to card", e)
            false
        } finally {
            try {
                mifareCard.close()
            } catch (e: Exception) {
                Log.e(TAG, "Error closing card", e)
            }
        }
    }

    private fun generateCardConfiguration(): Map<String, String> {
        return mapOf(
            "userId" to binding.userIdEditText.text.toString().trim(),
            "doors" to binding.accessDoorsEditText.text.toString().trim(),
            "startDate" to binding.startDateEditText.text.toString().trim(),
            "endDate" to binding.endDateEditText.text.toString().trim(),
            "accessLevel" to getSelectedAccessLevel(),
            "notes" to binding.notesEditText.text.toString().trim(),
            "issuerData" to binding.issuerDataEditText.text.toString().trim(),
            "cardType" to "mifare_classic_1k",
            "timestamp" to System.currentTimeMillis().toString()
        )
    }

    private fun getSelectedAccessLevel(): String {
        return when (binding.accessLevelSpinner.selectedItemPosition) {
            0 -> "guest"
            1 -> "resident"
            2 -> "staff"
            3 -> "manager"
            4 -> "admin"
            else -> "guest"
        }
    }

    private fun generateSampleData() {
        binding.userIdEditText.setText((10000..99999).random().toString())

        val sampleDoors = listOf("101", "102", "103", "201", "202", "301", "302", "401", "501")
        val selectedDoors = sampleDoors.shuffled().take((2..5).random())
        binding.accessDoorsEditText.setText(selectedDoors.joinToString(","))

        val now = java.time.Instant.now()
        val startDate = now.plusSeconds((0..7200).random().toLong()) // 0-2 hours from now
        val endDate = startDate.plusSeconds((86400..2592000).random().toLong()) // 1-30 days later

        binding.startDateEditText.setText(startDate.toString())
        binding.endDateEditText.setText(endDate.toString())

        binding.accessLevelSpinner.setSelection((0..4).random())
        binding.notesEditText.setText("Auto-generated sample data")

        showMessage("Sample data generated")
    }

    private fun previewCardData() {
        if (!validateInputs()) return

        val config = generateCardConfiguration()
        val saltoData = SaltoProtocol.generateSaltoPayload(config)

        val preview = buildString {
            append("=== CARD CONFIGURATION PREVIEW ===\n\n")
            append("User ID: ${config["userId"]}\n")
            append("Access Doors: ${config["doors"]}\n")
            append("Valid From: ${config["startDate"]}\n")
            append("Valid Until: ${config["endDate"]}\n")
            append("Access Level: ${config["accessLevel"]}\n")
            append("Notes: ${config["notes"]}\n\n")

            append("=== GENERATED SALTO DATA ===\n")
            append("Payload Size: ${saltoData.size} bytes\n")
            append("Hex Data: ${MifareUtils.bytesToHex(saltoData)}\n\n")

            append("=== WRITE PREVIEW ===\n")
            append("This data will be written to MIFARE sectors\n")
            append("Authentication will use default keys\n")
            append("Existing data will be overwritten\n")
        }

        androidx.appcompat.app.AlertDialog.Builder(requireContext())
            .setTitle("Card Configuration Preview")
            .setMessage(preview)
            .setPositiveButton("Close", null)
            .setNeutralButton("Copy") { _, _ ->
                val clipboard = requireContext().getSystemService(android.content.Context.CLIPBOARD_SERVICE) as android.content.ClipboardManager
                val clip = android.content.ClipData.newPlainText("Card Preview", preview)
                clipboard.setPrimaryClip(clip)
                showMessage("Preview copied to clipboard")
            }
            .show()
    }

    private fun resetForm() {
        binding.userIdEditText.text?.clear()
        binding.accessDoorsEditText.text?.clear()
        binding.startDateEditText.text?.clear()
        binding.endDateEditText.text?.clear()
        binding.notesEditText.text?.clear()
        binding.issuerDataEditText.text?.clear()
        binding.accessLevelSpinner.setSelection(0)

        binding.statusText.text = "Form reset. Enter new configuration."
        binding.statusText.setBackgroundColor(resources.getColor(android.R.color.transparent, null))

        disableWriteMode()
        showMessage("Form cleared")
    }

    private fun showDatePicker(onDateSelected: (String) -> Unit) {
        val calendar = java.util.Calendar.getInstance()

        val datePickerDialog = android.app.DatePickerDialog(
            requireContext(),
            { _, year, month, dayOfMonth ->
                val timePickerDialog = android.app.TimePickerDialog(
                    requireContext(),
                    { _, hourOfDay, minute ->
                        val instant = java.time.LocalDateTime.of(year, month + 1, dayOfMonth, hourOfDay, minute)
                            .atZone(java.time.ZoneId.systemDefault())
                            .toInstant()
                        onDateSelected(instant.toString())
                    },
                    calendar.get(java.util.Calendar.HOUR_OF_DAY),
                    calendar.get(java.util.Calendar.MINUTE),
                    true
                )
                timePickerDialog.show()
            },
            calendar.get(java.util.Calendar.YEAR),
            calendar.get(java.util.Calendar.MONTH),
            calendar.get(java.util.Calendar.DAY_OF_MONTH)
        )

        datePickerDialog.show()
    }

    private fun showMessage(message: String) {
        Toast.makeText(requireContext(), message, Toast.LENGTH_SHORT).show()
    }

    override fun onDestroyView() {
        super.onDestroyView()
        _binding = null
    }
}

package com.mifare.encoder.models

data class CardData(
    var uid: String = "",
    var type: String = "",
    var size: String = "",
    var sectors: List<String> = emptyList(),
    var saltoData: SaltoData? = null
)

data class SaltoData(
    var userId: String = "",
    var accessRights: List<String> = emptyList(),
    var doorList: List<String> = emptyList(),
    var startTimestamp: String = "",
    var endTimestamp: String = "",
    var checksum: String = "",
    var rawData: Map<String, String> = emptyMap(),
    var isValid: Boolean = false
)

data class CustomCardConfig(
    var userId: String = "",
    var accessDoors: String = "",
    var startDate: String = "",
    var endDate: String = "",
    var notes: String = "",
    var additionalData: Map<String, String> = emptyMap()
)

data class RemoteConfig(
    var backendUrl: String = "",
    var apiKey: String = "",
    var isConnected: Boolean = false,
    var lastSync: String = ""
)

data class ApiResponse(
    var success: Boolean = false,
    var message: String = "",
    var data: ByteArray? = null,
    var cardData: String = ""
) {
    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (javaClass != other?.javaClass) return false

        other as ApiResponse

        if (success != other.success) return false
        if (message != other.message) return false
        if (data != null) {
            if (other.data == null) return false
            if (!data.contentEquals(other.data)) return false
        } else if (other.data != null) return false
        if (cardData != other.cardData) return false

        return true
    }

    override fun hashCode(): Int {
        var result = success.hashCode()
        result = 31 * result + message.hashCode()
        result = 31 * result + (data?.contentHashCode() ?: 0)
        result = 31 * result + cardData.hashCode()
        return result
    }
}

package com.mifare.encoder.utils

import android.util.Log
import com.google.gson.Gson
import com.mifare.encoder.models.ApiResponse
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import okhttp3.*
import okhttp3.MediaType.Companion.toMediaType
import okhttp3.RequestBody.Companion.toRequestBody
import java.io.IOException
import java.net.URL
import java.util.concurrent.TimeUnit

class ApiClient(private val baseUrl: String, private val apiKey: String) {

    private val client = OkHttpClient.Builder()
        .connectTimeout(30, TimeUnit.SECONDS)
        .readTimeout(30, TimeUnit.SECONDS)
        .writeTimeout(30, TimeUnit.SECONDS)
        .certificatePinner(getCertificatePinner())
        .build()

    private val gson = Gson()

    companion object {
        private const val TAG = "ApiClient"
        private val JSON = "application/json; charset=utf-8".toMediaType()
    }

    /**
     * Create certificate pinner for enhanced security
     * Production domains should have their actual certificate pins
     */
    private fun getCertificatePinner(): CertificatePinner {
        val builder = CertificatePinner.Builder()

        try {
            val host = URL(baseUrl).host

            // Add pins for production domains
            when {
                host.contains("513solutions.com") -> {
                    // Production certificate pins for 513solutions.com
                    // These should be updated with actual certificate pins
                    builder.add(host, "sha256/AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=") // Placeholder
                }
                host.contains("railway.app") -> {
                    // Railway.app certificate pins
                    builder.add(host, "sha256/AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=") // Placeholder
                }
                host.contains("render.com") -> {
                    // Render.com certificate pins
                    builder.add(host, "sha256/AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=") // Placeholder
                }
                else -> {
                    Log.w(TAG, "Certificate pinning not configured for host: $host")
                }
            }
        } catch (e: Exception) {
            Log.e(TAG, "Error configuring certificate pinning", e)
        }

        return builder.build()
    }

    /**
     * Test connection to the backend
     */
    suspend fun testConnection(): ApiResponse {
        return withContext(Dispatchers.IO) {
            try {
                val url = "$baseUrl/api/test"
                val request = Request.Builder()
                    .url(url)
                    .addHeader("Authorization", "Bearer $apiKey")
                    .get()
                    .build()

                val response = client.newCall(request).execute()

                if (response.isSuccessful) {
                    ApiResponse(
                        success = true,
                        message = "Connection successful"
                    )
                } else {
                    ApiResponse(
                        success = false,
                        message = "HTTP ${response.code}: ${response.message}"
                    )
                }

            } catch (e: Exception) {
                Log.e(TAG, "Test connection failed", e)
                ApiResponse(
                    success = false,
                    message = e.message ?: "Unknown error"
                )
            }
        }
    }

    /**
     * Generate card configuration from backend
     */
    suspend fun generateConfig(config: Map<String, String>): ApiResponse {
        return withContext(Dispatchers.IO) {
            try {
                val url = "$baseUrl/api/android/generate-config"
                val jsonBody = gson.toJson(config)

                val requestBody = jsonBody.toRequestBody(JSON)
                val request = Request.Builder()
                    .url(url)
                    .addHeader("Authorization", "Bearer $apiKey")
                    .addHeader("Content-Type", "application/json")
                    .post(requestBody)
                    .build()

                val response = client.newCall(request).execute()
                val responseBody = response.body?.string() ?: ""

                if (response.isSuccessful) {
                    val apiResponse = gson.fromJson(responseBody, ApiResponse::class.java)
                    apiResponse ?: ApiResponse(
                        success = false,
                        message = "Invalid response format"
                    )
                } else {
                    ApiResponse(
                        success = false,
                        message = "HTTP ${response.code}: $responseBody"
                    )
                }

            } catch (e: Exception) {
                Log.e(TAG, "Generate config failed", e)
                ApiResponse(
                    success = false,
                    message = e.message ?: "Unknown error"
                )
            }
        }
    }

    /**
     * Submit card programming result to backend
     */
    suspend fun submitProgrammingResult(
        userId: String,
        cardUid: String,
        success: Boolean,
        errorMessage: String? = null
    ): ApiResponse {
        return withContext(Dispatchers.IO) {
            try {
                val url = "$baseUrl/api/android/programming-result"
                val data = mapOf(
                    "userId" to userId,
                    "cardUid" to cardUid,
                    "success" to success.toString(),
                    "errorMessage" to (errorMessage ?: ""),
                    "timestamp" to System.currentTimeMillis().toString()
                )

                val jsonBody = gson.toJson(data)
                val requestBody = jsonBody.toRequestBody(JSON)

                val request = Request.Builder()
                    .url(url)
                    .addHeader("Authorization", "Bearer $apiKey")
                    .addHeader("Content-Type", "application/json")
                    .post(requestBody)
                    .build()

                val response = client.newCall(request).execute()
                val responseBody = response.body?.string() ?: ""

                if (response.isSuccessful) {
                    ApiResponse(
                        success = true,
                        message = "Result submitted successfully"
                    )
                } else {
                    ApiResponse(
                        success = false,
                        message = "HTTP ${response.code}: $responseBody"
                    )
                }

            } catch (e: Exception) {
                Log.e(TAG, "Submit result failed", e)
                ApiResponse(
                    success = false,
                    message = e.message ?: "Unknown error"
                )
            }
        }
    }

    /**
     * Get available card programs from backend
     */
    suspend fun getAvailablePrograms(): ApiResponse {
        return withContext(Dispatchers.IO) {
            try {
                val url = "$baseUrl/api/android/programs"
                val request = Request.Builder()
                    .url(url)
                    .addHeader("Authorization", "Bearer $apiKey")
                    .get()
                    .build()

                val response = client.newCall(request).execute()
                val responseBody = response.body?.string() ?: ""

                if (response.isSuccessful) {
                    ApiResponse(
                        success = true,
                        message = "Programs retrieved successfully",
                        cardData = responseBody
                    )
                } else {
                    ApiResponse(
                        success = false,
                        message = "HTTP ${response.code}: $responseBody"
                    )
                }

            } catch (e: Exception) {
                Log.e(TAG, "Get programs failed", e)
                ApiResponse(
                    success = false,
                    message = e.message ?: "Unknown error"
                )
            }
        }
    }
}

package com.mifare.encoder.utils

import android.content.Context
import android.content.SharedPreferences
import android.util.Log
import androidx.security.crypto.EncryptedSharedPreferences
import androidx.security.crypto.MasterKey
import java.security.MessageDigest

class AuthManager(private val context: Context) {

    private val encryptedPrefs: SharedPreferences

    companion object {
        private const val TAG = "AuthManager"
        private const val PREFS_NAME = "auth_prefs"
        private const val KEY_ADMIN_PASSWORD_HASH = "admin_password_hash"
        private const val KEY_IS_ADMIN_MODE = "is_admin_mode"
        private const val KEY_ADMIN_SESSION_TIMEOUT = "admin_session_timeout"
        private const val KEY_FIRST_RUN_PASSWORD_CHANGED = "first_run_password_changed"
        private const val DEFAULT_ADMIN_PASSWORD = "admin123"
        private const val SESSION_TIMEOUT_MS = 30 * 60 * 1000L // 30 minutes

        @Volatile
        private var INSTANCE: AuthManager? = null

        fun getInstance(context: Context): AuthManager {
            return INSTANCE ?: synchronized(this) {
                INSTANCE ?: AuthManager(context.applicationContext).also { INSTANCE = it }
            }
        }
    }

    init {
        val masterKey = MasterKey.Builder(context)
            .setKeyScheme(MasterKey.KeyScheme.AES256_GCM)
            .build()

        encryptedPrefs = EncryptedSharedPreferences.create(
            context,
            PREFS_NAME,
            masterKey,
            EncryptedSharedPreferences.PrefKeyEncryptionScheme.AES256_SIV,
            EncryptedSharedPreferences.PrefValueEncryptionScheme.AES256_GCM
        )

        // Initialize default password if not set
        if (!encryptedPrefs.contains(KEY_ADMIN_PASSWORD_HASH)) {
            setAdminPassword(DEFAULT_ADMIN_PASSWORD)
            // Mark as needing password change on first run
            encryptedPrefs.edit()
                .putBoolean(KEY_FIRST_RUN_PASSWORD_CHANGED, false)
                .apply()
        }
    }

    fun isAdminMode(): Boolean {
        val isAdminMode = encryptedPrefs.getBoolean(KEY_IS_ADMIN_MODE, false)
        val sessionTimeout = encryptedPrefs.getLong(KEY_ADMIN_SESSION_TIMEOUT, 0)

        // Check if session has expired
        if (isAdminMode && System.currentTimeMillis() > sessionTimeout) {
            setUserMode()
            return false
        }

        return isAdminMode
    }

    fun authenticateAdmin(password: String): Boolean {
        val inputHash = hashPassword(password)
        val storedHash = encryptedPrefs.getString(KEY_ADMIN_PASSWORD_HASH, "")

        val isValid = inputHash == storedHash

        if (isValid) {
            setAdminMode()
            logAdminAction("Admin authentication successful")
        } else {
            logAdminAction("Admin authentication failed for password attempt")
        }

        return isValid
    }

    fun isFirstRunPasswordChangeRequired(): Boolean {
        // Check flag first
        val hasChangedFlag = encryptedPrefs.getBoolean(KEY_FIRST_RUN_PASSWORD_CHANGED, false)

        // Always check if current password is still the default, regardless of flag
        val currentHash = encryptedPrefs.getString(KEY_ADMIN_PASSWORD_HASH, "")
        val defaultHash = hashPassword(DEFAULT_ADMIN_PASSWORD)

        return !hasChangedFlag || currentHash == defaultHash
    }

    fun markFirstRunPasswordChanged() {
        encryptedPrefs.edit()
            .putBoolean(KEY_FIRST_RUN_PASSWORD_CHANGED, true)
            .apply()
        logAdminAction("First-run password change completed")
    }

    fun setAdminMode() {
        val sessionTimeout = System.currentTimeMillis() + SESSION_TIMEOUT_MS
        encryptedPrefs.edit()
            .putBoolean(KEY_IS_ADMIN_MODE, true)
            .putLong(KEY_ADMIN_SESSION_TIMEOUT, sessionTimeout)
            .apply()

        logAdminAction("Switched to admin mode")
    }

    fun setUserMode() {
        encryptedPrefs.edit()
            .putBoolean(KEY_IS_ADMIN_MODE, false)
            .putLong(KEY_ADMIN_SESSION_TIMEOUT, 0)
            .apply()

        logAdminAction("Switched to user mode")
    }

    fun setAdminPassword(newPassword: String) {
        val passwordHash = hashPassword(newPassword)
        encryptedPrefs.edit()
            .putString(KEY_ADMIN_PASSWORD_HASH, passwordHash)
            .apply()

        logAdminAction("Admin password updated")
    }

    fun extendSession() {
        if (isAdminMode()) {
            val newTimeout = System.currentTimeMillis() + SESSION_TIMEOUT_MS
            encryptedPrefs.edit()
                .putLong(KEY_ADMIN_SESSION_TIMEOUT, newTimeout)
                .apply()
        }
    }

    private fun hashPassword(password: String): String {
        val digest = MessageDigest.getInstance("SHA-256")
        val hashBytes = digest.digest(password.toByteArray())
        return hashBytes.joinToString("") { "%02x".format(it) }
    }

    private fun logAdminAction(action: String) {
        val timestamp = System.currentTimeMillis()
        Log.i(TAG, "[$timestamp] Admin Action: $action")

        // Store admin action logs in preferences for viewing in admin mode
        val existingLogs = encryptedPrefs.getString("admin_logs", "")
        val newLog = "[$timestamp] $action\n"
        val updatedLogs = (existingLogs + newLog).takeLast(5000) // Keep last 5000 chars

        encryptedPrefs.edit()
            .putString("admin_logs", updatedLogs)
            .apply()
    }

    fun getAdminLogs(): String {
        return encryptedPrefs.getString("admin_logs", "No admin actions logged.") ?: "No admin actions logged."
    }

    fun clearAdminLogs() {
        encryptedPrefs.edit()
            .putString("admin_logs", "")
            .apply()
        logAdminAction("Admin logs cleared")
    }
}

package com.mifare.encoder.utils

import android.util.Log
import java.nio.ByteBuffer
import java.security.MessageDigest
import java.util.*

object MifareUtils {

    private const val TAG = "MifareUtils"

    /**
     * Convert byte array to hexadecimal string
     */
    fun bytesToHex(bytes: ByteArray): String {
        val hexChars = "0123456789ABCDEF"
        val result = StringBuilder(bytes.size * 2)

        for (byte in bytes) {
            val i = byte.toInt()
            result.append(hexChars[i shr 4 and 0x0F])
            result.append(hexChars[i and 0x0F])
        }

        return result.toString()
    }

    /**
     * Convert hexadecimal string to byte array
     */
    fun hexToBytes(hex: String): ByteArray {
        val cleanHex = hex.replace(" ", "").replace(":", "")
        val len = cleanHex.length
        val data = ByteArray(len / 2)

        for (i in 0 until len step 2) {
            data[i / 2] = ((Character.digit(cleanHex[i], 16) shl 4) + 
                          Character.digit(cleanHex[i + 1], 16)).toByte()
        }

        return data
    }

    /**
     * Calculate CRC16 checksum (common in RFID protocols)
     */
    fun calculateCRC16(data: ByteArray): Int {
        var crc = 0xFFFF

        for (byte in data) {
            crc = crc xor (byte.toInt() and 0xFF)
            for (i in 0 until 8) {
                if (crc and 0x0001 != 0) {
                    crc = (crc shr 1) xor 0xA001
                } else {
                    crc = crc shr 1
                }
            }
        }

        return crc and 0xFFFF
    }

    /**
     * Calculate MD5 hash
     */
    fun calculateMD5(data: ByteArray): String {
        val md = MessageDigest.getInstance("MD5")
        val digest = md.digest(data)
        return bytesToHex(digest)
    }

    /**
     * Extract integer from byte array at given offset
     */
    fun bytesToInt(bytes: ByteArray, offset: Int = 0, length: Int = 4): Int {
        val buffer = ByteBuffer.allocate(4)
        val dataLength = minOf(length, bytes.size - offset)

        if (dataLength <= 0) return 0

        // Fill with zeros first, then add actual data
        buffer.put(ByteArray(4 - dataLength))
        buffer.put(bytes, offset, dataLength)
        buffer.flip()

        return buffer.int
    }

    /**
     * Convert integer to byte array
     */
    fun intToBytes(value: Int, length: Int = 4): ByteArray {
        val buffer = ByteBuffer.allocate(4)
        buffer.putInt(value)
        val fullBytes = buffer.array()

        return if (length < 4) {
            fullBytes.sliceArray((4 - length) until 4)
        } else {
            fullBytes
        }
    }

    /**
     * Extract timestamp from byte array (assumes Unix timestamp format)
     */
    fun bytesToTimestamp(bytes: ByteArray, offset: Int = 0): Date? {
        return try {
            val timestamp = bytesToInt(bytes, offset).toLong()
            if (timestamp > 0) Date(timestamp * 1000) else null
        } catch (e: Exception) {
            Log.w(TAG, "Failed to parse timestamp", e)
            null
        }
    }

    /**
     * Convert timestamp to byte array
     */
    fun timestampToBytes(date: Date): ByteArray {
        val timestamp = (date.time / 1000).toInt()
        return intToBytes(timestamp)
    }

    /**
     * Parse ISO 8601 date string to Date
     */
    fun parseISODate(dateString: String): Date? {
        return try {
            val calendar = Calendar.getInstance()
            // Simple ISO date parsing - could be enhanced with proper ISO parser
            val parts = dateString.split("T", "-", ":")
            if (parts.size >= 6) {
                calendar.set(
                    parts[0].toInt(), // year
                    parts[1].toInt() - 1, // month (0-based)
                    parts[2].toInt(), // day
                    parts[3].toInt(), // hour
                    parts[4].toInt(), // minute
                    parts[5].substringBefore('.').substringBefore('Z').toInt() // second
                )
                calendar.time
            } else null
        } catch (e: Exception) {
            Log.w(TAG, "Failed to parse ISO date: $dateString", e)
            null
        }
    }

    /**
     * Format date to ISO 8601 string
     */
    fun formatISODate(date: Date): String {
        val calendar = Calendar.getInstance()
        calendar.time = date
        return String.format(
            "%04d-%02d-%02dT%02d:%02d:%02dZ",
            calendar.get(Calendar.YEAR),
            calendar.get(Calendar.MONTH) + 1,
            calendar.get(Calendar.DAY_OF_MONTH),
            calendar.get(Calendar.HOUR_OF_DAY),
            calendar.get(Calendar.MINUTE),
            calendar.get(Calendar.SECOND)
        )
    }

    /**
     * Validate MIFARE Classic block data
     */
    fun isValidBlockData(data: ByteArray): Boolean {
        return data.size == 16 // MIFARE Classic block size
    }

    /**
     * Check if data contains potential text/ASCII content
     */
    fun containsReadableText(data: ByteArray): Boolean {
        var readableCount = 0
        for (byte in data) {
            val b = byte.toInt() and 0xFF
            if (b in 32..126 || b == 9 || b == 10 || b == 13) { // Printable ASCII + common whitespace
                readableCount++
            }
        }
        return readableCount > data.size / 2 // More than half should be readable
    }

    /**
     * Extract readable text from byte array
     */
    fun extractReadableText(data: ByteArray): String {
        return String(data.filter { byte ->
            val b = byte.toInt() and 0xFF
            b in 32..126 || b == 9 || b == 10 || b == 13
        }.toByteArray()).trim()
    }

    /**
     * Write card data to MIFARE card (simplified implementation for user mode)
     */
    fun writeCardData(mifareCard: android.nfc.tech.MifareClassic, config: Map<String, String>): Boolean {
        return try {
            Log.d(TAG, "Writing card data to MIFARE card")

            // Extract configuration data
            val userId = config["userId"] ?: "default"
            val accessCode = config["accessCode"] ?: "1234"
            val validUntil = config["validUntil"] ?: formatISODate(java.util.Date(System.currentTimeMillis() + 30L * 24 * 3600 * 1000))

            // Create data block with user info
            val userData = "$userId:$accessCode:$validUntil"
            val dataBytes = userData.toByteArray()

            // Pad to 16 bytes (MIFARE block size)
            val paddedData = ByteArray(16)
            System.arraycopy(dataBytes, 0, paddedData, 0, minOf(dataBytes.size, 16))

            // Write to sector 1, block 1 (avoiding sector trailer)
            val sectorIndex = 1
            val blockIndex = mifareCard.sectorToBlock(sectorIndex) + 1

            // Authenticate with default key
            val defaultKey = byteArrayOf(0xFF.toByte(), 0xFF.toByte(), 0xFF.toByte(), 0xFF.toByte(), 0xFF.toByte(), 0xFF.toByte())

            if (mifareCard.authenticateSectorWithKeyA(sectorIndex, defaultKey)) {
                mifareCard.writeBlock(blockIndex, paddedData)
                Log.d(TAG, "Card data written successfully")
                true
            } else {
                Log.e(TAG, "Authentication failed for sector $sectorIndex")
                false
            }

        } catch (e: Exception) {
            Log.e(TAG, "Failed to write card data", e)
            false
        }
    }

    /**
     * Read card data from MIFARE card
     */
    fun readCardData(mifareCard: android.nfc.tech.MifareClassic): Map<String, String>? {
        return try {
            Log.d(TAG, "Reading card data from MIFARE card")

            val sectorIndex = 1
            val blockIndex = mifareCard.sectorToBlock(sectorIndex) + 1

            // Authenticate with default key
            val defaultKey = byteArrayOf(0xFF.toByte(), 0xFF.toByte(), 0xFF.toByte(), 0xFF.toByte(), 0xFF.toByte(), 0xFF.toByte())

            if (mifareCard.authenticateSectorWithKeyA(sectorIndex, defaultKey)) {
                val data = mifareCard.readBlock(blockIndex)
                val userData = extractReadableText(data)

                if (userData.isNotEmpty()) {
                    val parts = userData.split(":")
                    if (parts.size >= 3) {
                        mapOf(
                            "userId" to parts[0],
                            "accessCode" to parts[1],
                            "validUntil" to parts[2],
                            "rawData" to bytesToHex(data)
                        )
                    } else {
                        mapOf("rawData" to bytesToHex(data))
                    }
                } else {
                    mapOf("rawData" to bytesToHex(data))
                }
            } else {
                Log.e(TAG, "Authentication failed for sector $sectorIndex")
                null
            }

        } catch (e: Exception) {
            Log.e(TAG, "Failed to read card data", e)
            null
        }
    }
}

package com.mifare.encoder.utils

import android.util.Log
import com.mifare.encoder.models.CustomCardConfig
import com.mifare.encoder.models.SaltoData
import java.util.*

object SaltoProtocol {

    private const val TAG = "SaltoProtocol"

    // Salto protocol assumptions based on common MIFARE access control patterns
    private const val MAD_SECTOR = 0
    private const val USER_DATA_SECTOR = 1
    private const val ACCESS_LIST_START_SECTOR = 2
    private const val ACCESS_LIST_END_SECTOR = 4
    private const val TIMESTAMP_SECTOR = 5
    private const val CHECKSUM_SECTOR = 15 // Usually last sector

    /**
     * Analyze card data to extract Salto protocol information
     */
    fun analyzeCard(sectorData: List<String>): SaltoData {
        val saltoData = SaltoData()
        val rawData = mutableMapOf<String, String>()

        try {
            // Process each sector
            for ((index, sector) in sectorData.withIndex()) {
                val sectorHex = sector.substringAfter(": ")
                if (sectorHex == "Authentication failed") continue

                val sectorBytes = MifareUtils.hexToBytes(sectorHex)
                rawData["sector_$index"] = sectorHex

                when (index) {
                    MAD_SECTOR -> {
                        // Sector 0 - MAD (MIFARE Application Directory)
                        analyzeMadSector(sectorBytes, saltoData)
                    }
                    USER_DATA_SECTOR -> {
                        // Sector 1 - User data
                        analyzeUserDataSector(sectorBytes, saltoData)
                    }
                    in ACCESS_LIST_START_SECTOR..ACCESS_LIST_END_SECTOR -> {
                        // Sectors 2-4 - Access lists
                        analyzeAccessListSector(sectorBytes, saltoData, index)
                    }
                    TIMESTAMP_SECTOR -> {
                        // Sector 5 - Timestamps
                        analyzeTimestampSector(sectorBytes, saltoData)
                    }
                    CHECKSUM_SECTOR -> {
                        // Last sector - Checksum/validation
                        analyzeChecksumSector(sectorBytes, saltoData)
                    }
                }
            }

            saltoData.rawData = rawData
            saltoData.isValid = validateSaltoData(saltoData)

        } catch (e: Exception) {
            Log.e(TAG, "Error analyzing card data", e)
            saltoData.isValid = false
        }

        return saltoData
    }

    /**
     * Analyze MAD sector (sector 0)
     */
    private fun analyzeMadSector(data: ByteArray, saltoData: SaltoData) {
        if (data.size < 16) return

        // Look for Salto application identifiers
        val madInfo = MifareUtils.extractReadableText(data)
        if (madInfo.contains("SALTO", ignoreCase = true)) {
            Log.d(TAG, "Salto MAD detected: $madInfo")
        }
    }

    /**
     * Analyze user data sector
     */
    private fun analyzeUserDataSector(data: ByteArray, saltoData: SaltoData) {
        if (data.size < 16) return

        try {
            // Assume user ID is in first 4 bytes
            val userId = MifareUtils.bytesToInt(data, 0, 4)
            if (userId > 0 && userId < 0xFFFFFF) { // Reasonable user ID range
                saltoData.userId = userId.toString()
            }

            // Look for readable text that might be user info
            val userText = MifareUtils.extractReadableText(data)
            if (userText.isNotEmpty()) {
                Log.d(TAG, "User data text: $userText")
            }

        } catch (e: Exception) {
            Log.w(TAG, "Error analyzing user data sector", e)
        }
    }

    /**
     * Analyze access list sectors
     */
    private fun analyzeAccessListSector(data: ByteArray, saltoData: SaltoData, sectorIndex: Int) {
        if (data.size < 16) return

        try {
            val doorList = mutableListOf<String>()

            // Parse door/room access rights (assume each door is 2 bytes)
            for (i in data.indices step 2) {
                if (i + 1 < data.size) {
                    val doorId = MifareUtils.bytesToInt(data, i, 2)
                    if (doorId > 0 && doorId < 9999) { // Reasonable door ID range
                        doorList.add(doorId.toString())
                    }
                }
            }

            if (doorList.isNotEmpty()) {
                saltoData.doorList = saltoData.doorList + doorList
            }

            // Look for access level flags
            val accessFlags = data[data.size - 1].toInt() and 0xFF
            if (accessFlags != 0) {
                val accessRights = mutableListOf<String>()
                if (accessFlags and 0x01 != 0) accessRights.add("ENTRY")
                if (accessFlags and 0x02 != 0) accessRights.add("EXIT")
                if (accessFlags and 0x04 != 0) accessRights.add("ADMIN")
                if (accessFlags and 0x08 != 0) accessRights.add("MAINTENANCE")

                saltoData.accessRights = saltoData.accessRights + accessRights
            }

        } catch (e: Exception) {
            Log.w(TAG, "Error analyzing access list sector $sectorIndex", e)
        }
    }

    /**
     * Analyze timestamp sector
     */
    private fun analyzeTimestampSector(data: ByteArray, saltoData: SaltoData) {
        if (data.size < 16) return

        try {
            // Assume start timestamp in first 4 bytes
            val startTime = MifareUtils.bytesToTimestamp(data, 0)
            if (startTime != null) {
                saltoData.startTimestamp = MifareUtils.formatISODate(startTime)
            }

            // Assume end timestamp in next 4 bytes
            val endTime = MifareUtils.bytesToTimestamp(data, 4)
            if (endTime != null) {
                saltoData.endTimestamp = MifareUtils.formatISODate(endTime)
            }

        } catch (e: Exception) {
            Log.w(TAG, "Error analyzing timestamp sector", e)
        }
    }

    /**
     * Analyze checksum sector
     */
    private fun analyzeChecksumSector(data: ByteArray, saltoData: SaltoData) {
        if (data.size < 16) return

        try {
            // Assume checksum in last 2 bytes
            val checksum = MifareUtils.bytesToInt(data, data.size - 2, 2)
            saltoData.checksum = String.format("%04X", checksum)

        } catch (e: Exception) {
            Log.w(TAG, "Error analyzing checksum sector", e)
        }
    }

    /**
     * Validate extracted Salto data
     */
    private fun validateSaltoData(saltoData: SaltoData): Boolean {
        return saltoData.userId.isNotEmpty() &&
               saltoData.doorList.isNotEmpty() &&
               saltoData.startTimestamp.isNotEmpty() &&
               saltoData.endTimestamp.isNotEmpty()
    }

    /**
     * Generate custom card data based on user input
     */
    fun generateCustomCardData(config: CustomCardConfig): ByteArray {
        val cardData = ByteArray(1024) // 1K card size
        var offset = 0

        try {
            // Skip sector 0 (manufacturer data)
            offset = 64 // Start at sector 1

            // Sector 1: User data
            val userId = config.userId.toIntOrNull() ?: 1
            System.arraycopy(MifareUtils.intToBytes(userId), 0, cardData, offset, 4)
            offset += 16 // Next block

            // Sectors 2-4: Access lists
            val doors = config.accessDoors.split(",").mapNotNull { it.trim().toIntOrNull() }
            for (door in doors.take(24)) { // Max 24 doors across 3 sectors
                System.arraycopy(MifareUtils.intToBytes(door, 2), 0, cardData, offset, 2)
                offset += 2
                if (offset % 16 == 0) offset += 16 // Skip to next block after each 16 bytes
            }

            // Align to sector 5 (timestamp sector)
            offset = 80 // Sector 5 start

            // Timestamps
            val startDate = MifareUtils.parseISODate(config.startDate)
            if (startDate != null) {
                System.arraycopy(MifareUtils.timestampToBytes(startDate), 0, cardData, offset, 4)
            }
            offset += 4

            val endDate = MifareUtils.parseISODate(config.endDate)
            if (endDate != null) {
                System.arraycopy(MifareUtils.timestampToBytes(endDate), 0, cardData, offset, 4)
            }

            // Calculate and add checksum at the end (sector 15)
            val checksumData = cardData.sliceArray(0 until 1008) // All data except checksum sector
            val checksum = MifareUtils.calculateCRC16(checksumData)
            val checksumOffset = 1008 // Last sector
            System.arraycopy(MifareUtils.intToBytes(checksum, 2), 0, cardData, checksumOffset, 2)

        } catch (e: Exception) {
            Log.e(TAG, "Error generating custom card data", e)
        }

        return cardData
    }

    /**
     * Validate custom configuration
     */
    fun validateCustomConfig(config: CustomCardConfig): List<String> {
        val errors = mutableListOf<String>()

        if (config.userId.isEmpty() || config.userId.toIntOrNull() == null) {
            errors.add("User ID must be a valid number")
        }

        if (config.accessDoors.isEmpty()) {
            errors.add("Access doors cannot be empty")
        } else {
            val doors = config.accessDoors.split(",")
            for (door in doors) {
                if (door.trim().toIntOrNull() == null) {
                    errors.add("Invalid door number: ${door.trim()}")
                }
            }
        }

        if (config.startDate.isEmpty() || MifareUtils.parseISODate(config.startDate) == null) {
            errors.add("Start date must be in ISO format (YYYY-MM-DDTHH:MM:SSZ)")
        }

        if (config.endDate.isEmpty() || MifareUtils.parseISODate(config.endDate) == null) {
            errors.add("End date must be in ISO format (YYYY-MM-DDTHH:MM:SSZ)")
        }

        // Validate date order
        val startDate = MifareUtils.parseISODate(config.startDate)
        val endDate = MifareUtils.parseISODate(config.endDate)
        if (startDate != null && endDate != null && startDate.after(endDate)) {
            errors.add("Start date must be before end date")
        }

        // Validate future dates
        val now = Date()
        if (endDate != null && endDate.before(now)) {
            errors.add("End date must be in the future")
        }

        return errors
    }
}
